// SPDX-License-Identifier: GPL-2.0
/*
 * lib/agent_kunit.c: KUnit test written by an agent for this benchmark.
 * This file is compiled when CONFIG_AGENT_KUNIT_TEST is set.
 *
 * Test suite for strncasecmp() from lib/string.c.
 */

#include <kunit/test.h>
#include <linux/string.h>

/* Identical strings compare equal regardless of len. */
static void strncasecmp_identical(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strncasecmp("hello", "hello", 5), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("hello", "hello", 100), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("hello", "hello", 1), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("", "", 10), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("a", "a", 1), 0);
}

/* Case differences are ignored. */
static void strncasecmp_case_insensitive(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strncasecmp("hello", "HELLO", 5), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("HeLLo", "hElLO", 5), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("abc", "ABC", 10), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("ABC", "abc", 10), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("Z", "z", 1), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("A", "a", 1), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("MiXeD CaSe 123", "mixed case 123", 14), 0);
}

/* Different strings: sign of result reflects first differing char. */
static void strncasecmp_different(struct kunit *test)
{
	KUNIT_EXPECT_LT(test, strncasecmp("abc", "abd", 3), 0);
	KUNIT_EXPECT_GT(test, strncasecmp("abd", "abc", 3), 0);
	KUNIT_EXPECT_LT(test, strncasecmp("ABC", "abd", 3), 0);
	KUNIT_EXPECT_GT(test, strncasecmp("ABD", "abc", 3), 0);
	KUNIT_EXPECT_LT(test, strncasecmp("apple", "banana", 10), 0);
	KUNIT_EXPECT_GT(test, strncasecmp("Banana", "APPLE", 10), 0);
}

/* Exact return value is the difference of the lowercased chars. */
static void strncasecmp_exact_return_value(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strncasecmp("abc", "abd", 3), 'c' - 'd');
	KUNIT_EXPECT_EQ(test, strncasecmp("abd", "abc", 3), 'd' - 'c');
	KUNIT_EXPECT_EQ(test, strncasecmp("ABC", "abd", 3), 'c' - 'd');
	KUNIT_EXPECT_EQ(test, strncasecmp("abC", "ABd", 3), 'c' - 'd');
	KUNIT_EXPECT_EQ(test, strncasecmp("A", "Z", 1), 'a' - 'z');
	KUNIT_EXPECT_EQ(test, strncasecmp("z", "A", 1), 'z' - 'a');
	/* Non-letters are returned as-is. */
	KUNIT_EXPECT_EQ(test, strncasecmp("1", "9", 1), '1' - '9');
}

/* len == 0 always yields 0, even for completely different strings. */
static void strncasecmp_zero_len(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strncasecmp("abc", "xyz", 0), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("", "xyz", 0), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("abc", "", 0), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("a", "b", 0), 0);
}

/* Only the first len chars are compared. */
static void strncasecmp_len_limits_comparison(struct kunit *test)
{
	/* Differ at index 3; len 3 ignores it, len 4 sees it. */
	KUNIT_EXPECT_EQ(test, strncasecmp("abcX", "ABCY", 3), 0);
	KUNIT_EXPECT_LT(test, strncasecmp("abcX", "ABCY", 4), 0);
	KUNIT_EXPECT_GT(test, strncasecmp("abcY", "ABCX", 4), 0);

	/* Differ at index 0; len 1 must detect it. */
	KUNIT_EXPECT_LT(test, strncasecmp("a", "b", 1), 0);
	KUNIT_EXPECT_GT(test, strncasecmp("B", "a", 1), 0);

	/* Prefix equality with large len vs limited len. */
	KUNIT_EXPECT_EQ(test, strncasecmp("hello world", "HELLO there", 6), 0);
	KUNIT_EXPECT_LT(test, strncasecmp("hello there", "HELLO world", 7), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("hello there", "HELLO world", 100) < 0,
			true);
}

/* Off-by-one around len: the len-th char (index len-1) is compared. */
static void strncasecmp_boundary_last_char(struct kunit *test)
{
	const char *a = "abcdefgh";
	const char *b = "ABCDEFGX";

	KUNIT_EXPECT_EQ(test, strncasecmp(a, b, 7), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp(a, b, 8), 'h' - 'x');
	KUNIT_EXPECT_EQ(test, strncasecmp(b, a, 8), 'x' - 'h');
	KUNIT_EXPECT_EQ(test, strncasecmp(a, b, 9), 'h' - 'x');
	KUNIT_EXPECT_EQ(test, strncasecmp(a, b, SIZE_MAX), 'h' - 'x');

	/* Difference exactly at index len (one past): must be ignored. */
	KUNIT_EXPECT_EQ(test, strncasecmp("abcdefgh", "ABCDEFGHZ", 8), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("abcdefghZ", "ABCDEFGH", 8), 0);
}

/* Strings of different lengths; NUL terminator is honoured. */
static void strncasecmp_different_lengths(struct kunit *test)
{
	/* Equal within len even though one is longer. */
	KUNIT_EXPECT_EQ(test, strncasecmp("abc", "ABCDEF", 3), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("abcdef", "ABC", 3), 0);

	/* Shorter string is "less" when len exceeds its length. */
	KUNIT_EXPECT_LT(test, strncasecmp("abc", "ABCDEF", 4), 0);
	KUNIT_EXPECT_GT(test, strncasecmp("ABCDEF", "abc", 4), 0);
	KUNIT_EXPECT_LT(test, strncasecmp("abc", "ABCDEF", 100), 0);
	KUNIT_EXPECT_GT(test, strncasecmp("abcdef", "ABC", 100), 0);

	/* Exact value: NUL minus the (un-lowercased) next char. */
	KUNIT_EXPECT_EQ(test, strncasecmp("abc", "abcd", 10), 0 - 'd');
	KUNIT_EXPECT_EQ(test, strncasecmp("abcd", "abc", 10), 'd' - 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("abc", "ABCD", 10), 0 - 'D');
	KUNIT_EXPECT_EQ(test, strncasecmp("ABCD", "abc", 10), 'D' - 0);
}

/* Empty strings. */
static void strncasecmp_empty(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strncasecmp("", "", 1), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("", "", 100), 0);
	KUNIT_EXPECT_LT(test, strncasecmp("", "a", 1), 0);
	KUNIT_EXPECT_GT(test, strncasecmp("a", "", 1), 0);
	KUNIT_EXPECT_LT(test, strncasecmp("", "A", 5), 0);
	KUNIT_EXPECT_GT(test, strncasecmp("A", "", 5), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("", "a", 1), 0 - 'a');
	KUNIT_EXPECT_EQ(test, strncasecmp("a", "", 1), 'a' - 0);
}

/* Comparison must stop at the first NUL even when len is larger. */
static void strncasecmp_stops_at_nul(struct kunit *test)
{
	const char a[] = { 'a', 'b', '\0', 'X', 'Y', '\0' };
	const char b[] = { 'A', 'B', '\0', 'Q', 'R', '\0' };

	/* Bytes after the NUL differ but must not be examined. */
	KUNIT_EXPECT_EQ(test, strncasecmp(a, b, sizeof(a)), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp(a, b, 100), 0);
}

/* Non-alphabetic chars: only letters are case-folded. */
static void strncasecmp_non_alpha(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strncasecmp("123-_./", "123-_./", 7), 0);
	KUNIT_EXPECT_LT(test, strncasecmp("123", "124", 3), 0);
	KUNIT_EXPECT_GT(test, strncasecmp("124", "123", 3), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp("a-b", "A-B", 3), 0);
	KUNIT_EXPECT_LT(test, strncasecmp("a-b", "A_B", 3), 0);

	/* Space and symbols are not equal to letters. */
	KUNIT_EXPECT_NE(test, strncasecmp("a b", "a_b", 3), 0);
	KUNIT_EXPECT_NE(test, strncasecmp("a", " ", 1), 0);
}

/*
 * Characters that are NOT letters but sit in the ASCII gaps between
 * cases ('[' 0x5B.. '`' 0x60) must not be folded onto letters:
 * e.g. '@' (0x40) vs '`' (0x60) differ by 0x20 like 'A'/'a' but
 * must still compare unequal.
 */
static void strncasecmp_case_fold_only_letters(struct kunit *test)
{
	KUNIT_EXPECT_NE(test, strncasecmp("@", "`", 1), 0);
	KUNIT_EXPECT_NE(test, strncasecmp("[", "{", 1), 0);
	KUNIT_EXPECT_NE(test, strncasecmp("]", "}", 1), 0);
	KUNIT_EXPECT_NE(test, strncasecmp("^", "~", 1), 0);
	KUNIT_EXPECT_NE(test, strncasecmp("_", "\x7f", 1), 0);
	KUNIT_EXPECT_NE(test, strncasecmp("\\", "|", 1), 0);
	KUNIT_EXPECT_LT(test, strncasecmp("@", "`", 1), 0);
	KUNIT_EXPECT_GT(test, strncasecmp("`", "@", 1), 0);
}

/* Full alphabet round trip, each letter against its other case. */
static void strncasecmp_full_alphabet(struct kunit *test)
{
	const char *lower = "abcdefghijklmnopqrstuvwxyz";
	const char *upper = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
	char l[2] = { 0, 0 };
	char u[2] = { 0, 0 };
	int i;

	KUNIT_EXPECT_EQ(test, strncasecmp(lower, upper, 26), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp(upper, lower, 26), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp(lower, upper, 27), 0);

	for (i = 0; i < 26; i++) {
		l[0] = lower[i];
		u[0] = upper[i];
		KUNIT_EXPECT_EQ_MSG(test, strncasecmp(l, u, 1), 0,
				    "letter %c vs %c", l[0], u[0]);
		KUNIT_EXPECT_EQ_MSG(test, strncasecmp(u, l, 1), 0,
				    "letter %c vs %c", u[0], l[0]);
	}

	/* Adjacent letters in different cases are ordered correctly. */
	for (i = 0; i < 25; i++) {
		l[0] = lower[i];
		u[0] = upper[i + 1];
		KUNIT_EXPECT_EQ_MSG(test, strncasecmp(l, u, 1), -1,
				    "letter %c vs %c", l[0], u[0]);
		KUNIT_EXPECT_EQ_MSG(test, strncasecmp(u, l, 1), 1,
				    "letter %c vs %c", u[0], l[0]);
	}
}

/*
 * Characters >= 0x80 must be treated as unsigned: a high byte must
 * compare greater than any ASCII char, never negative.
 */
static void strncasecmp_high_bytes_unsigned(struct kunit *test)
{
	const char hi[] = { (char)0xff, '\0' };
	const char hi2[] = { (char)0x80, '\0' };
	const char lo[] = { 'a', '\0' };
	const char ctl[] = { 0x01, '\0' };

	KUNIT_EXPECT_GT(test, strncasecmp(hi, lo, 1), 0);
	KUNIT_EXPECT_LT(test, strncasecmp(lo, hi, 1), 0);
	KUNIT_EXPECT_GT(test, strncasecmp(hi2, lo, 1), 0);
	KUNIT_EXPECT_GT(test, strncasecmp(hi, hi2, 1), 0);
	KUNIT_EXPECT_LT(test, strncasecmp(hi2, hi, 1), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp(hi, hi, 1), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp(hi, lo, 1), 0xff - 'a');
	KUNIT_EXPECT_EQ(test, strncasecmp(lo, hi, 1), 'a' - 0xff);
	KUNIT_EXPECT_GT(test, strncasecmp(hi, ctl, 1), 0);
	KUNIT_EXPECT_LT(test, strncasecmp(ctl, hi, 1), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp(ctl, hi, 1), 0x01 - 0xff);
}

/* Symmetry: swapping the arguments negates the result. */
static void strncasecmp_antisymmetric(struct kunit *test)
{
	static const char * const pairs[][2] = {
		{ "abc", "abd" },
		{ "ABC", "abd" },
		{ "abc", "abcd" },
		{ "", "x" },
		{ "hello", "HELP" },
		{ "a", "B" },
		{ "same", "SAME" },
	};
	int i;

	for (i = 0; i < ARRAY_SIZE(pairs); i++) {
		int r1 = strncasecmp(pairs[i][0], pairs[i][1], 10);
		int r2 = strncasecmp(pairs[i][1], pairs[i][0], 10);

		KUNIT_EXPECT_EQ_MSG(test, r1, -r2, "pair \"%s\" / \"%s\"",
				    pairs[i][0], pairs[i][1]);
	}
}

/* Longer realistic inputs. */
static void strncasecmp_long_strings(struct kunit *test)
{
	char a[300];
	char b[300];
	int i;

	for (i = 0; i < 299; i++) {
		a[i] = 'a' + (i % 26);
		b[i] = 'A' + (i % 26);
	}
	a[299] = '\0';
	b[299] = '\0';

	KUNIT_EXPECT_EQ(test, strncasecmp(a, b, 299), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp(a, b, 1000), 0);

	/* Introduce a difference near the end. */
	b[298] = '!';
	KUNIT_EXPECT_EQ(test, strncasecmp(a, b, 298), 0);
	KUNIT_EXPECT_GT(test, strncasecmp(a, b, 299), 0);
	KUNIT_EXPECT_LT(test, strncasecmp(b, a, 299), 0);
	KUNIT_EXPECT_EQ(test, strncasecmp(a, b, 299), a[298] - '!');
}

static struct kunit_case agent_test_cases[] = {
	KUNIT_CASE(strncasecmp_identical),
	KUNIT_CASE(strncasecmp_case_insensitive),
	KUNIT_CASE(strncasecmp_different),
	KUNIT_CASE(strncasecmp_exact_return_value),
	KUNIT_CASE(strncasecmp_zero_len),
	KUNIT_CASE(strncasecmp_len_limits_comparison),
	KUNIT_CASE(strncasecmp_boundary_last_char),
	KUNIT_CASE(strncasecmp_different_lengths),
	KUNIT_CASE(strncasecmp_empty),
	KUNIT_CASE(strncasecmp_stops_at_nul),
	KUNIT_CASE(strncasecmp_non_alpha),
	KUNIT_CASE(strncasecmp_case_fold_only_letters),
	KUNIT_CASE(strncasecmp_full_alphabet),
	KUNIT_CASE(strncasecmp_high_bytes_unsigned),
	KUNIT_CASE(strncasecmp_antisymmetric),
	KUNIT_CASE(strncasecmp_long_strings),
	{}
};

static struct kunit_suite agent_test_suite = {
	.name = "agent_test",
	.test_cases = agent_test_cases,
};

kunit_test_suite(agent_test_suite);

MODULE_DESCRIPTION("KUnit tests for strncasecmp()");
MODULE_LICENSE("GPL");

// SPDX-License-Identifier: GPL-2.0
/*
 * lib/agent_kunit.c: KUnit test written by an agent for this benchmark.
 * This file is compiled when CONFIG_AGENT_KUNIT_TEST is set.
 *
 * Test suite for strcspn() from lib/string.c.
 */
#include <kunit/test.h>
#include <linux/string.h>

/* Reject set is a single char found in the middle. */
static void strcspn_basic(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("hello world", " "), 5);
	KUNIT_EXPECT_EQ(test, strcspn("abcdef", "d"), 3);
	KUNIT_EXPECT_EQ(test, strcspn("abcdef", "c"), 2);
}

/* Reject set with several characters; first match in s wins. */
static void strcspn_multi_reject(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("abcdef", "fed"), 3);
	KUNIT_EXPECT_EQ(test, strcspn("abcdef", "xyzb"), 1);
	KUNIT_EXPECT_EQ(test, strcspn("key=value;rest", ";="), 3);
	KUNIT_EXPECT_EQ(test, strcspn("key=value;rest", ";"), 9);
}

/* No reject character present: whole string length is returned. */
static void strcspn_no_match(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("abcdef", "xyz"), 6);
	KUNIT_EXPECT_EQ(test, strcspn("abcdef", "g"), 6);
	KUNIT_EXPECT_EQ(test, strcspn("a", "b"), 1);
	KUNIT_EXPECT_EQ(test, strcspn("abcdef", "xyz"), strlen("abcdef"));
}

/* Empty reject set never matches: returns strlen(s). */
static void strcspn_empty_reject(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("abcdef", ""), 6);
	KUNIT_EXPECT_EQ(test, strcspn("a", ""), 1);
	KUNIT_EXPECT_EQ(test, strcspn("", ""), 0);
}

/* Empty source string always yields 0. */
static void strcspn_empty_string(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("", "abc"), 0);
	KUNIT_EXPECT_EQ(test, strcspn("", "a"), 0);
}

/* Match at the very first character returns 0. */
static void strcspn_match_first(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("abcdef", "a"), 0);
	KUNIT_EXPECT_EQ(test, strcspn("abcdef", "zya"), 0);
	KUNIT_EXPECT_EQ(test, strcspn("a", "a"), 0);
	KUNIT_EXPECT_EQ(test, strcspn("aaaa", "a"), 0);
}

/* Match at the very last character returns strlen(s) - 1. */
static void strcspn_match_last(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("abcdef", "f"), 5);
	KUNIT_EXPECT_EQ(test, strcspn("abcdef", "xf"), 5);
	KUNIT_EXPECT_EQ(test, strcspn("ab", "b"), 1);
}

/*
 * The NUL terminator of s must never be treated as a member of reject,
 * even though strchr(reject, '\0') would find the terminator of reject.
 * Equally, the terminator of reject must not match ordinary chars.
 */
static void strcspn_nul_not_in_reject(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("abc", "xyz"), 3);
	KUNIT_EXPECT_EQ(test, strcspn("abc", ""), 3);
	KUNIT_EXPECT_EQ(test, strcspn("", "xyz"), 0);
}

/* Only the first match counts; later occurrences do not extend the span. */
static void strcspn_repeated_chars(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("abcabc", "c"), 2);
	KUNIT_EXPECT_EQ(test, strcspn("aabbcc", "b"), 2);
	KUNIT_EXPECT_EQ(test, strcspn("xxxxxy", "y"), 5);
	KUNIT_EXPECT_EQ(test, strcspn("abcdef", "ff"), 5);
}

/* Whole-string prefix: s is entirely composed of reject chars except one. */
static void strcspn_reject_superset(struct kunit *test)
{
	/* every char of s is in reject -> 0 */
	KUNIT_EXPECT_EQ(test, strcspn("abc", "abcdef"), 0);
	/* reject is s itself */
	KUNIT_EXPECT_EQ(test, strcspn("abc", "abc"), 0);
	/* reject contains all but first char of s */
	KUNIT_EXPECT_EQ(test, strcspn("abc", "bc"), 1);
}

/* Case sensitivity: 'A' and 'a' are distinct. */
static void strcspn_case_sensitive(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, strcspn("abcABC", "A"), 3);
	KUNIT_EXPECT_EQ(test, strcspn("abcABC", "a"), 0);
	KUNIT_EXPECT_EQ(test, strcspn("ABC", "abc"), 3);
}

/* Non-alphanumeric and high-bit characters. */
static void strcspn_special_chars(struct kunit *test)
{
	static const char hi[] = { 'a', 'b', (char)0xff, 'c', '\0' };
	static const char rej[] = { (char)0xff, '\0' };
	static const char rej2[] = { (char)0x80, '\0' };

	KUNIT_EXPECT_EQ(test, strcspn("a\tb\nc", "\n"), 3);
	KUNIT_EXPECT_EQ(test, strcspn("a\tb\nc", "\t"), 1);
	KUNIT_EXPECT_EQ(test, strcspn("path/to/file", "/"), 4);
	KUNIT_EXPECT_EQ(test, strcspn(hi, rej), 2);
	KUNIT_EXPECT_EQ(test, strcspn(hi, rej2), 4);
}

/* Result is consistent with strpbrk(). */
static void strcspn_matches_strpbrk(struct kunit *test)
{
	static const char *const strs[] = {
		"", "a", "abcdef", "hello, world!", "aaaaab", "x=y;z",
	};
	static const char *const rejs[] = {
		"", "a", "b", "f", "xyz", ";=", " !,",
	};
	size_t i, j;

	for (i = 0; i < ARRAY_SIZE(strs); i++) {
		for (j = 0; j < ARRAY_SIZE(rejs); j++) {
			const char *s = strs[i];
			const char *r = rejs[j];
			const char *p = strpbrk(s, r);
			size_t expect = p ? (size_t)(p - s) : strlen(s);

			KUNIT_EXPECT_EQ_MSG(test, strcspn(s, r), expect,
					    "s=\"%s\" reject=\"%s\"", s, r);
		}
	}
}

/* Longer buffer with the reject char at every possible position. */
static void strcspn_sweep_positions(struct kunit *test)
{
	char buf[65];
	size_t i;

	memset(buf, 'a', sizeof(buf) - 1);
	buf[sizeof(buf) - 1] = '\0';

	KUNIT_EXPECT_EQ(test, strcspn(buf, "b"), sizeof(buf) - 1);

	for (i = 0; i < sizeof(buf) - 1; i++) {
		buf[i] = 'b';
		KUNIT_EXPECT_EQ_MSG(test, strcspn(buf, "b"), i, "i=%zu", i);
		buf[i] = 'a';
	}
}

/* Result never exceeds strlen(s). */
static void strcspn_bounded_by_strlen(struct kunit *test)
{
	static const char *const strs[] = { "", "a", "ab", "abcdef", "zzzz" };
	size_t i;

	for (i = 0; i < ARRAY_SIZE(strs); i++) {
		KUNIT_EXPECT_LE(test, strcspn(strs[i], "q"), strlen(strs[i]));
		KUNIT_EXPECT_EQ(test, strcspn(strs[i], "q"), strlen(strs[i]));
	}
}

static struct kunit_case agent_test_cases[] = {
	KUNIT_CASE(strcspn_basic),
	KUNIT_CASE(strcspn_multi_reject),
	KUNIT_CASE(strcspn_no_match),
	KUNIT_CASE(strcspn_empty_reject),
	KUNIT_CASE(strcspn_empty_string),
	KUNIT_CASE(strcspn_match_first),
	KUNIT_CASE(strcspn_match_last),
	KUNIT_CASE(strcspn_nul_not_in_reject),
	KUNIT_CASE(strcspn_repeated_chars),
	KUNIT_CASE(strcspn_reject_superset),
	KUNIT_CASE(strcspn_case_sensitive),
	KUNIT_CASE(strcspn_special_chars),
	KUNIT_CASE(strcspn_matches_strpbrk),
	KUNIT_CASE(strcspn_sweep_positions),
	KUNIT_CASE(strcspn_bounded_by_strlen),
	{}
};

static struct kunit_suite agent_test_suite = {
	.name = "agent_test",
	.test_cases = agent_test_cases,
};

kunit_test_suite(agent_test_suite);

MODULE_DESCRIPTION("KUnit tests for strcspn()");
MODULE_LICENSE("GPL");

// SPDX-License-Identifier: GPL-2.0
/*
 * lib/agent_kunit.c: KUnit test written by an agent for this benchmark.
 * This file is compiled when CONFIG_AGENT_KUNIT_TEST is set.
 *
 * Tests for string_get_size() in lib/string_helpers.c.
 */

#include <kunit/test.h>
#include <linux/string.h>
#include <linux/string_helpers.h>

#define SGS_BUF 32

struct sgs_case {
	u64 size;
	u64 blk;
	const char *exp10;
	const char *exp2;
};

static void sgs_check(struct kunit *test, u64 size, u64 blk,
		      enum string_size_units units, const char *exp)
{
	char buf[SGS_BUF];
	int ret;

	memset(buf, 'X', sizeof(buf));
	ret = string_get_size(size, blk, units, buf, sizeof(buf));
	KUNIT_EXPECT_STREQ_MSG(test, buf, exp,
			       "size=%llu blk=%llu units=%#x", size, blk, units);
	KUNIT_EXPECT_EQ_MSG(test, ret, (int)strlen(exp),
			    "size=%llu blk=%llu units=%#x buf=\"%s\"",
			    size, blk, units, buf);
}

static void sgs_check_table(struct kunit *test, const struct sgs_case *tbl,
			    size_t n)
{
	size_t k;

	for (k = 0; k < n; k++) {
		sgs_check(test, tbl[k].size, tbl[k].blk, STRING_UNITS_10,
			  tbl[k].exp10);
		sgs_check(test, tbl[k].size, tbl[k].blk, STRING_UNITS_2,
			  tbl[k].exp2);
	}
}

/* Zero size and zero block size always yield "0 B". */
static void sgs_zero(struct kunit *test)
{
	static const struct sgs_case tbl[] = {
		{ 0,		1,		"0 B",	"0 B" },
		{ 0,		4096,		"0 B",	"0 B" },
		{ 1,		0,		"0 B",	"0 B" },
		{ 12345,	0,		"0 B",	"0 B" },
		{ U64_MAX,	0,		"0 B",	"0 B" },
		{ 0,		U64_MAX,	"0 B",	"0 B" },
		{ 0,		0,		"0 B",	"0 B" },
	};

	sgs_check_table(test, tbl, ARRAY_SIZE(tbl));
}

/* Values below one unit: precision depends on number of integer digits. */
static void sgs_bytes(struct kunit *test)
{
	static const struct sgs_case tbl[] = {
		{ 1,	1,	"1.00 B",	"1.00 B" },
		{ 9,	1,	"9.00 B",	"9.00 B" },
		{ 10,	1,	"10.0 B",	"10.0 B" },
		{ 99,	1,	"99.0 B",	"99.0 B" },
		{ 100,	1,	"100 B",	"100 B" },
		{ 512,	1,	"512 B",	"512 B" },
		{ 999,	1,	"999 B",	"999 B" },
		{ 1,	512,	"512 B",	"512 B" },
	};

	sgs_check_table(test, tbl, ARRAY_SIZE(tbl));
}

/* The 1000 / 1024 boundary where the two unit systems diverge. */
static void sgs_kilo_boundary(struct kunit *test)
{
	static const struct sgs_case tbl[] = {
		{ 999,	1,	"999 B",	"999 B" },
		{ 1000,	1,	"1.00 kB",	"1000 B" },
		{ 1001,	1,	"1.00 kB",	"1001 B" },
		{ 1023,	1,	"1.02 kB",	"1023 B" },
		{ 1024,	1,	"1.02 kB",	"1.00 KiB" },
		{ 1025,	1,	"1.03 kB",	"1.00 KiB" },
		{ 2,	512,	"1.02 kB",	"1.00 KiB" },
		{ 3,	1024,	"3.07 kB",	"3.00 KiB" },
		{ 1,	4096,	"4.10 kB",	"4.00 KiB" },
	};

	sgs_check_table(test, tbl, ARRAY_SIZE(tbl));
}

/* Decimal rounding at the half-way point for each precision level. */
static void sgs_rounding_units10(struct kunit *test)
{
	static const struct sgs_case tbl[] = {
		/* two decimals: round digit is thousandths */
		{ 1004,		1,	"1.00 kB",	"1004 B" },
		{ 1005,		1,	"1.01 kB",	"1005 B" },
		{ 1994,		1,	"1.99 kB",	"1.95 KiB" },
		{ 1995,		1,	"2.00 kB",	"1.95 KiB" },
		{ 1999,		1,	"2.00 kB",	"1.95 KiB" },
		/* one decimal: round digit is hundredths */
		{ 10049,	1,	"10.0 kB",	"9.81 KiB" },
		{ 10050,	1,	"10.1 kB",	"9.81 KiB" },
		{ 99949,	1,	"99.9 kB",	"97.6 KiB" },
		{ 99950,	1,	"100.0 kB",	"97.6 KiB" },
		/* no decimals: round digit is tenths */
		{ 999499,	1,	"999 kB",	"976 KiB" },
		{ 999500,	1,	"1000 kB",	"976 KiB" },
		{ 999999,	1,	"1000 kB",	"977 KiB" },
	};

	sgs_check_table(test, tbl, ARRAY_SIZE(tbl));
}

/* Binary remainders are scaled from /1024 to /1000 before rounding. */
static void sgs_rounding_units2(struct kunit *test)
{
	static const struct sgs_case tbl[] = {
		{ 1029,		1,	"1.03 kB",	"1.00 KiB" },
		{ 1030,		1,	"1.03 kB",	"1.01 KiB" },
		{ 1535,		1,	"1.54 kB",	"1.50 KiB" },
		{ 1536,		1,	"1.54 kB",	"1.50 KiB" },
		{ 2047,		1,	"2.05 kB",	"2.00 KiB" },
		{ 2048,		1,	"2.05 kB",	"2.00 KiB" },
		{ 10239,	1,	"10.2 kB",	"10.00 KiB" },
		{ 10240,	1,	"10.2 kB",	"10.0 KiB" },
		{ 102400,	1,	"102 kB",	"100 KiB" },
		{ 1048575,	1,	"1.05 MB",	"1024 KiB" },
		{ 1048576,	1,	"1.05 MB",	"1.00 MiB" },
	};

	sgs_check_table(test, tbl, ARRAY_SIZE(tbl));
}

/* Significant-figure selection across 1, 2 and 3 integer digits. */
static void sgs_precision(struct kunit *test)
{
	static const struct sgs_case tbl[] = {
		{ 9999,		1,	"10.00 kB",	"9.76 KiB" },
		{ 10000,	1,	"10.0 kB",	"9.77 KiB" },
		{ 99999,	1,	"100.0 kB",	"97.7 KiB" },
		{ 100000,	1,	"100 kB",	"97.7 KiB" },
		{ 1000000,	1,	"1.00 MB",	"977 KiB" },
		{ 4096,		512,	"2.10 MB",	"2.00 MiB" },
	};

	sgs_check_table(test, tbl, ARRAY_SIZE(tbl));
}

/* Walk every unit prefix with exact powers. */
static void sgs_all_prefixes(struct kunit *test)
{
	static const struct sgs_case tbl[] = {
		{ 1ULL << 10,	1,	"1.02 kB",	"1.00 KiB" },
		{ 1ULL << 20,	1,	"1.05 MB",	"1.00 MiB" },
		{ 1ULL << 30,	1,	"1.07 GB",	"1.00 GiB" },
		{ 1ULL << 40,	1,	"1.10 TB",	"1.00 TiB" },
		{ 1ULL << 50,	1,	"1.13 PB",	"1.00 PiB" },
		{ 1ULL << 60,	1,	"1.15 EB",	"1.00 EiB" },
		{ 1000ULL,			1, "1.00 kB", "1000 B" },
		{ 1000000ULL,			1, "1.00 MB", "977 KiB" },
		{ 1000000000ULL,		1, "1.00 GB", "954 MiB" },
		{ 1000000000000ULL,		1, "1.00 TB", "931 GiB" },
		{ 1000000000000000ULL,		1, "1.00 PB", "909 TiB" },
		{ 1000000000000000000ULL,	1, "1.00 EB", "888 PiB" },
	};

	sgs_check_table(test, tbl, ARRAY_SIZE(tbl));
}

/* Inputs above 32 bits exercise the pre-reduction loops. */
static void sgs_large_values(struct kunit *test)
{
	static const struct sgs_case tbl[] = {
		{ (1ULL << 40) - 1,	1,	"1.10 TB",	"1024 GiB" },
		{ 1ULL << 63,		1,	"9.22 EB",	"8.00 EiB" },
		{ U64_MAX,		1,	"18.4 EB",	"16.0 EiB" },
		{ 10000000000000000000ULL, 1,	"10.0 EB",	"8.67 EiB" },
		{ 1ULL << 31,	1ULL << 31,	"4.61 EB",	"4.00 EiB" },
		{ U32_MAX,	U32_MAX,	"18.4 EB",	"16.0 EiB" },
		{ 1ULL << 32,	1ULL << 32,	"18.4 EB",	"16.0 EiB" },
		{ 1,		U64_MAX,	"18.4 EB",	"16.0 EiB" },
		{ U64_MAX,	1024,		"18.9 ZB",	"16.0 ZiB" },
		{ U64_MAX,	4096,		"75.6 ZB",	"64.0 ZiB" },
	};

	sgs_check_table(test, tbl, ARRAY_SIZE(tbl));
}

/* Beyond the last known prefix the unit becomes "UNK". */
static void sgs_unknown_unit(struct kunit *test)
{
	static const struct sgs_case tbl[] = {
		{ U64_MAX,	U64_MAX,	"340 UNKB",	"256 UNKB" },
	};
	char buf[SGS_BUF];

	sgs_check_table(test, tbl, ARRAY_SIZE(tbl));

	/* Y is still a known prefix, 2^80 bytes exactly */
	string_get_size(1ULL << 40, 1ULL << 40, STRING_UNITS_2, buf, sizeof(buf));
	KUNIT_EXPECT_STREQ(test, buf, "1.00 YiB");
	string_get_size(1ULL << 40, 1ULL << 40, STRING_UNITS_10, buf, sizeof(buf));
	KUNIT_EXPECT_STREQ(test, buf, "1.21 YB");

	/* 2^80 * 1024 = 2^90 overflows the table */
	string_get_size(1ULL << 50, 1ULL << 40, STRING_UNITS_2, buf, sizeof(buf));
	KUNIT_EXPECT_STREQ(test, buf, "1.00 UNKB");
}

/* STRING_UNITS_NO_SPACE and STRING_UNITS_NO_BYTES flags. */
static void sgs_flags(struct kunit *test)
{
	sgs_check(test, 0, 1, STRING_UNITS_10 | STRING_UNITS_NO_SPACE, "0B");
	sgs_check(test, 0, 1, STRING_UNITS_10 | STRING_UNITS_NO_BYTES, "0 ");
	sgs_check(test, 0, 1,
		  STRING_UNITS_10 | STRING_UNITS_NO_SPACE | STRING_UNITS_NO_BYTES,
		  "0");

	sgs_check(test, 1024, 1, STRING_UNITS_2 | STRING_UNITS_NO_SPACE,
		  "1.00KiB");
	sgs_check(test, 1024, 1, STRING_UNITS_2 | STRING_UNITS_NO_BYTES,
		  "1.00 Ki");
	sgs_check(test, 1024, 1,
		  STRING_UNITS_2 | STRING_UNITS_NO_SPACE | STRING_UNITS_NO_BYTES,
		  "1.00Ki");

	sgs_check(test, 1000, 1, STRING_UNITS_10 | STRING_UNITS_NO_SPACE,
		  "1.00kB");
	sgs_check(test, 1000, 1, STRING_UNITS_10 | STRING_UNITS_NO_BYTES,
		  "1.00 k");
	sgs_check(test, 1000, 1,
		  STRING_UNITS_10 | STRING_UNITS_NO_SPACE | STRING_UNITS_NO_BYTES,
		  "1.00k");

	/* bytes with no prefix */
	sgs_check(test, 512, 1, STRING_UNITS_2 | STRING_UNITS_NO_SPACE, "512B");
	sgs_check(test, 512, 1, STRING_UNITS_2 | STRING_UNITS_NO_BYTES, "512 ");

	/* flags must not change the base selection */
	sgs_check(test, 1024, 1, STRING_UNITS_10 | STRING_UNITS_NO_SPACE,
		  "1.02kB");
}

/* Truncation: snprintf semantics, always NUL terminated, len respected. */
static void sgs_truncation(struct kunit *test)
{
	char buf[SGS_BUF];
	int ret;

	/* exact fit: 8 chars + NUL */
	memset(buf, 'X', sizeof(buf));
	ret = string_get_size(1024, 1, STRING_UNITS_2, buf, 9);
	KUNIT_EXPECT_EQ(test, ret, 8);
	KUNIT_EXPECT_STREQ(test, buf, "1.00 KiB");
	KUNIT_EXPECT_EQ(test, buf[9], 'X');

	/* one short: last char dropped, NUL at buf[7] */
	memset(buf, 'X', sizeof(buf));
	ret = string_get_size(1024, 1, STRING_UNITS_2, buf, 8);
	KUNIT_EXPECT_EQ(test, ret, 8);
	KUNIT_EXPECT_STREQ(test, buf, "1.00 Ki");
	KUNIT_EXPECT_EQ(test, buf[7], '\0');
	KUNIT_EXPECT_EQ(test, buf[8], 'X');

	memset(buf, 'X', sizeof(buf));
	ret = string_get_size(1024, 1, STRING_UNITS_2, buf, 4);
	KUNIT_EXPECT_EQ(test, ret, 8);
	KUNIT_EXPECT_STREQ(test, buf, "1.0");
	KUNIT_EXPECT_EQ(test, buf[4], 'X');

	memset(buf, 'X', sizeof(buf));
	ret = string_get_size(1024, 1, STRING_UNITS_2, buf, 1);
	KUNIT_EXPECT_EQ(test, ret, 8);
	KUNIT_EXPECT_STREQ(test, buf, "");
	KUNIT_EXPECT_EQ(test, buf[1], 'X');

	/* len == 0: nothing written, full length still reported */
	memset(buf, 'X', sizeof(buf));
	ret = string_get_size(1024, 1, STRING_UNITS_2, buf, 0);
	KUNIT_EXPECT_EQ(test, ret, 8);
	KUNIT_EXPECT_EQ(test, buf[0], 'X');

	memset(buf, 'X', sizeof(buf));
	ret = string_get_size(0, 1, STRING_UNITS_10, buf, 2);
	KUNIT_EXPECT_EQ(test, ret, 3);
	KUNIT_EXPECT_STREQ(test, buf, "0");

	/* longest possible output is 9 characters */
	memset(buf, 'X', sizeof(buf));
	ret = string_get_size(10239, 1, STRING_UNITS_2, buf, 9);
	KUNIT_EXPECT_EQ(test, ret, 9);
	KUNIT_EXPECT_STREQ(test, buf, "10.00 Ki");
}

/* Return value equals the full formatted length for various shapes. */
static void sgs_return_length(struct kunit *test)
{
	char buf[SGS_BUF];

	KUNIT_EXPECT_EQ(test, string_get_size(0, 1, STRING_UNITS_10, buf,
					      sizeof(buf)), 3);
	KUNIT_EXPECT_EQ(test, string_get_size(5, 1, STRING_UNITS_10, buf,
					      sizeof(buf)), 6);
	KUNIT_EXPECT_EQ(test, string_get_size(50, 1, STRING_UNITS_10, buf,
					      sizeof(buf)), 6);
	KUNIT_EXPECT_EQ(test, string_get_size(500, 1, STRING_UNITS_10, buf,
					      sizeof(buf)), 5);
	KUNIT_EXPECT_EQ(test, string_get_size(5000, 1, STRING_UNITS_10, buf,
					      sizeof(buf)), 7);
	KUNIT_EXPECT_EQ(test, string_get_size(5000, 1, STRING_UNITS_2, buf,
					      sizeof(buf)), 8);
	KUNIT_EXPECT_EQ(test, string_get_size(1048575, 1, STRING_UNITS_2, buf,
					      sizeof(buf)), 8);
	KUNIT_EXPECT_EQ(test, string_get_size(0, 1,
					      STRING_UNITS_10 | STRING_UNITS_NO_SPACE |
					      STRING_UNITS_NO_BYTES,
					      buf, sizeof(buf)), 1);
	KUNIT_EXPECT_EQ(test, string_get_size(U64_MAX, U64_MAX, STRING_UNITS_10,
					      buf, sizeof(buf)), 8);
}

/* Block size and size commute: size*blk is what gets formatted. */
static void sgs_block_commutes(struct kunit *test)
{
	static const u64 vals[] = { 1, 7, 512, 1000, 1024, 4096, 65536, 1000003 };
	char a[SGS_BUF], b[SGS_BUF];
	size_t x, y;

	for (x = 0; x < ARRAY_SIZE(vals); x++) {
		for (y = 0; y < ARRAY_SIZE(vals); y++) {
			string_get_size(vals[x], vals[y], STRING_UNITS_10, a,
					sizeof(a));
			string_get_size(vals[y], vals[x], STRING_UNITS_10, b,
					sizeof(b));
			KUNIT_EXPECT_STREQ_MSG(test, a, b, "x=%llu y=%llu",
					       vals[x], vals[y]);
			string_get_size(vals[x], vals[y], STRING_UNITS_2, a,
					sizeof(a));
			string_get_size(vals[y], vals[x], STRING_UNITS_2, b,
					sizeof(b));
			KUNIT_EXPECT_STREQ_MSG(test, a, b, "x=%llu y=%llu",
					       vals[x], vals[y]);
			string_get_size(vals[x] * vals[y], 1, STRING_UNITS_2, b,
					sizeof(b));
			KUNIT_EXPECT_STREQ_MSG(test, a, b, "x=%llu y=%llu",
					       vals[x], vals[y]);
		}
	}
}

