/*
 * lib/agent_kunit.c: KUnit test written by an agent for this benchmark.
 * This file is compiled when CONFIG_AGENT_KUNIT_TEST is set.
 *
 * Test suite for string_escape_mem() from lib/string_helpers.c.
 */
#include <kunit/test.h>
#include <linux/string.h>
#include <linux/string_helpers.h>

#define POISON	0xA5
#define BUFSZ	256

/*
 * Run string_escape_mem() with a large, poisoned output buffer and check that
 * the return value equals the expected length, exactly the expected bytes were
 * written, and nothing past the end was touched.
 */
static void check_escape(struct kunit *test, const char *src, size_t isz,
			 unsigned int flags, const char *only,
			 const char *exp, size_t explen)
{
	char out[BUFSZ];
	int ret;

	KUNIT_ASSERT_LT(test, explen, (size_t)BUFSZ);

	memset(out, POISON, sizeof(out));
	ret = string_escape_mem(src, isz, out, sizeof(out), flags, only);

	KUNIT_EXPECT_EQ_MSG(test, ret, (int)explen,
			    "flags=%#x only=%s", flags, only ? only : "(null)");
	KUNIT_EXPECT_MEMEQ_MSG(test, out, exp, explen,
			       "flags=%#x only=%s", flags, only ? only : "(null)");
	/* The function must not write a terminator or anything beyond ret */
	KUNIT_EXPECT_EQ(test, (unsigned char)out[explen], POISON);
	KUNIT_EXPECT_EQ(test, (unsigned char)out[BUFSZ - 1], POISON);
}

/*
 * For every output size from 0 up to explen + 1, verify that the return
 * value is always the full length, that exactly min(osz, explen) bytes are
 * written, and that bytes beyond osz are untouched.
 */
static void check_truncation(struct kunit *test, const char *src, size_t isz,
			     unsigned int flags, const char *only,
			     const char *exp, size_t explen)
{
	char out[BUFSZ];
	size_t osz, i;
	int ret;

	KUNIT_ASSERT_LT(test, explen + 2, (size_t)BUFSZ);

	for (osz = 0; osz <= explen + 1; osz++) {
		size_t written = min(osz, explen);

		memset(out, POISON, sizeof(out));
		ret = string_escape_mem(src, isz, out, osz, flags, only);

		KUNIT_EXPECT_EQ_MSG(test, ret, (int)explen, "osz=%zu", osz);
		KUNIT_EXPECT_MEMEQ_MSG(test, out, exp, written, "osz=%zu", osz);
		for (i = written; i < written + 4; i++)
			KUNIT_EXPECT_EQ_MSG(test, (unsigned char)out[i], POISON,
					    "osz=%zu i=%zu", osz, i);
	}
}

#define CHECK(test, src, flags, only, exp) \
	check_escape(test, src, sizeof(src) - 1, flags, only, exp, sizeof(exp) - 1)
#define CHECK_TRUNC(test, src, flags, only, exp) \
	check_truncation(test, src, sizeof(src) - 1, flags, only, exp, sizeof(exp) - 1)

/* ---- Normal behaviour of each class ---- */

static void agent_test_no_flags_passthrough(struct kunit *test)
{
	static const char src[] = "a\n\t\\\"\a\e\0\x80\xff z";

	/* With no flags at all, every byte is copied verbatim. */
	CHECK(test, src, 0, NULL, src);
	CHECK(test, src, 0, "", src);
}

static void agent_test_zero_length_input(struct kunit *test)
{
	char out[8];
	int ret;

	memset(out, POISON, sizeof(out));
	ret = string_escape_mem("abc", 0, out, sizeof(out), ESCAPE_ANY_NP, NULL);
	KUNIT_EXPECT_EQ(test, ret, 0);
	KUNIT_EXPECT_EQ(test, (unsigned char)out[0], POISON);

	/* Zero input and zero output must be a no-op too. */
	ret = string_escape_mem("abc", 0, out, 0, ESCAPE_ANY_NP, NULL);
	KUNIT_EXPECT_EQ(test, ret, 0);
	KUNIT_EXPECT_EQ(test, (unsigned char)out[0], POISON);
}

static void agent_test_space(struct kunit *test)
{
	/* Every ESCAPE_SPACE member, plus a plain space which must NOT escape */
	CHECK(test, "\f\n\r\t\v ", ESCAPE_SPACE, NULL, "\\f\\n\\r\\t\\v ");
	/* Characters belonging to other classes are untouched */
	CHECK(test, "\\\"\a\e\0\x80", ESCAPE_SPACE, NULL, "\\\"\a\e\0\x80");
	/* Interleaved with printable text */
	CHECK(test, "a\nb\tc", ESCAPE_SPACE, NULL, "a\\nb\\tc");
}

static void agent_test_special(struct kunit *test)
{
	CHECK(test, "\\\a\e\"", ESCAPE_SPECIAL, NULL, "\\\\\\a\\e\\\"");
	/* Other classes stay as-is */
	CHECK(test, "\n\t\0\x80\x7f", ESCAPE_SPECIAL, NULL, "\n\t\0\x80\x7f");
	CHECK(test, "x\\y", ESCAPE_SPECIAL, NULL, "x\\\\y");
}

static void agent_test_null(struct kunit *test)
{
	static const char src[] = "a\0b\0";

	/* sizeof(src) - 1 == 4, embedded NULs must be processed */
	check_escape(test, src, 4, ESCAPE_NULL, NULL, "a\\0b\\0", 6);
	/* Nothing else is affected by ESCAPE_NULL */
	CHECK(test, "\n\\\x80\x01", ESCAPE_NULL, NULL, "\n\\\x80\x01");
	/* '0' is not NUL */
	CHECK(test, "0", ESCAPE_NULL, NULL, "0");
}

static void agent_test_octal(struct kunit *test)
{
	/* ESCAPE_OCTAL escapes *every* byte, including printable ones */
	CHECK(test, "\0\1\7\x08", ESCAPE_OCTAL, NULL, "\\000\\001\\007\\010");
	CHECK(test, "A", ESCAPE_OCTAL, NULL, "\\101");
	CHECK(test, "\xff", ESCAPE_OCTAL, NULL, "\\377");
	CHECK(test, "\x80", ESCAPE_OCTAL, NULL, "\\200");
	CHECK(test, "\x3f\x40", ESCAPE_OCTAL, NULL, "\\077\\100");
	CHECK(test, " ", ESCAPE_OCTAL, NULL, "\\040");
}

static void agent_test_hex(struct kunit *test)
{
	CHECK(test, "\0\x01\x0f\x10", ESCAPE_HEX, NULL, "\\x00\\x01\\x0f\\x10");
	CHECK(test, "A", ESCAPE_HEX, NULL, "\\x41");
	CHECK(test, "\xff\x80\x7f", ESCAPE_HEX, NULL, "\\xff\\x80\\x7f");
	/* hex digits must be lowercase */
	CHECK(test, "\xab\xcd\xef", ESCAPE_HEX, NULL, "\\xab\\xcd\\xef");
}

static void agent_test_octal_wins_over_hex(struct kunit *test)
{
	CHECK(test, "A\xff", ESCAPE_OCTAL | ESCAPE_HEX, NULL, "\\101\\377");
}

static void agent_test_all_bytes_octal_and_hex(struct kunit *test)
{
	unsigned char src[256];
	char out[256 * 4];
	int ret, i;

	for (i = 0; i < 256; i++)
		src[i] = i;

	ret = string_escape_mem(src, sizeof(src), out, sizeof(out),
				ESCAPE_OCTAL, NULL);
	KUNIT_ASSERT_EQ(test, ret, 256 * 4);
	for (i = 0; i < 256; i++) {
		char exp[4] = { '\\', '0' + ((i >> 6) & 7), '0' + ((i >> 3) & 7),
				'0' + (i & 7) };
		KUNIT_EXPECT_MEMEQ_MSG(test, out + i * 4, exp, 4, "byte %#x", i);
	}

	ret = string_escape_mem(src, sizeof(src), out, sizeof(out),
				ESCAPE_HEX, NULL);
	KUNIT_ASSERT_EQ(test, ret, 256 * 4);
	for (i = 0; i < 256; i++) {
		char exp[4] = { '\\', 'x', hex_asc_hi(i), hex_asc_lo(i) };
		KUNIT_EXPECT_MEMEQ_MSG(test, out + i * 4, exp, 4, "byte %#x", i);
	}
}

/* ---- Class precedence ---- */

static void agent_test_precedence(struct kunit *test)
{
	/* SPACE beats OCTAL/HEX, SPECIAL beats OCTAL/HEX, NULL beats OCTAL/HEX */
	CHECK(test, "\n", ESCAPE_SPACE | ESCAPE_OCTAL, NULL, "\\n");
	CHECK(test, "\n", ESCAPE_SPACE | ESCAPE_HEX, NULL, "\\n");
	CHECK(test, "\\", ESCAPE_SPECIAL | ESCAPE_OCTAL, NULL, "\\\\");
	CHECK(test, "\0", ESCAPE_NULL | ESCAPE_HEX, NULL, "\\0");
	/* Without the specific class, the generic one applies */
	CHECK(test, "\n", ESCAPE_OCTAL, NULL, "\\012");
	CHECK(test, "\0", ESCAPE_HEX, NULL, "\\x00");
	CHECK(test, "\\", ESCAPE_HEX, NULL, "\\x5c");
	/* ESCAPE_ANY == SPACE|SPECIAL|NULL|OCTAL */
	CHECK(test, "\n\\\0\x01" "A", ESCAPE_ANY, NULL,
	      "\\n\\\\\\0\\001\\101");
}

/* ---- Printable / ASCII filters ---- */

static void agent_test_np(struct kunit *test)
{
	/* Printable ASCII passes through, non-printables are escaped */
	CHECK(test, "a ~\x7f\x1f\0\n", ESCAPE_NP | ESCAPE_OCTAL, NULL,
	      "a ~\\177\\037\\000\\012");
	/*
	 * ESCAPE_ANY_NP uses the specific classes for space/null, but the
	 * printable '\\' and '"' pass through before ESCAPE_SPECIAL is tried.
	 */
	CHECK(test, "a\n\0\\\"\x01\x7f", ESCAPE_ANY_NP, NULL,
	      "a\\n\\0\\\"\\001\\177");
	/* 0xfe/0xff are printable Latin-1 in the kernel ctype table */
	CHECK(test, "\xfe\xff", ESCAPE_ANY_NP, NULL, "\xfe\xff");
	/* 0x80 is not printable in kernel ctype: escaped */
	CHECK(test, "\x80", ESCAPE_NP | ESCAPE_HEX, NULL, "\\x80");
	/* 0xe9 is marked printable (Latin-1) in kernel ctype: passes through */
	CHECK(test, "\xe9", ESCAPE_NP | ESCAPE_HEX, NULL, "\xe9");
	/* ESCAPE_NP without an escaping class: nothing is escaped */
	CHECK(test, "\x01\x80", ESCAPE_NP, NULL, "\x01\x80");
	/* Boundaries of printable ASCII: 0x1f/0x20 and 0x7e/0x7f */
	CHECK(test, "\x1f\x20\x7e\x7f", ESCAPE_NP | ESCAPE_HEX, NULL,
	      "\\x1f \x7e\\x7f");
}

static void agent_test_na(struct kunit *test)
{
	/* Any ASCII (even non-printable) passes, non-ASCII is escaped */
	CHECK(test, "a\n\0\x7f\x80\xe9\xff", ESCAPE_NA | ESCAPE_HEX, NULL,
	      "a\n\0\x7f\\x80\\xe9\\xff");
	/* NA has priority over SPACE/SPECIAL/NULL for ASCII characters */
	CHECK(test, "\n\\\0\x80", ESCAPE_NA | ESCAPE_ANY, NULL,
	      "\n\\\0\\200");
	/* Boundary: 0x7f is ASCII, 0x80 is not */
	CHECK(test, "\x7f\x80", ESCAPE_NA | ESCAPE_OCTAL, NULL, "\x7f\\200");
}

static void agent_test_nap(struct kunit *test)
{
	/* Only printable ASCII passes; both non-printable and non-ASCII escape */
	CHECK(test, "a\n\x7f\x80\xe9", ESCAPE_NAP | ESCAPE_HEX, NULL,
	      "a\\x0a\\x7f\\x80\\xe9");
	/* NAP combined with SPACE/SPECIAL uses the specific classes */
	CHECK(test, "a\n\"\xe9\x01", ESCAPE_NAP | ESCAPE_SPACE | ESCAPE_SPECIAL |
	      ESCAPE_OCTAL, NULL, "a\\n\"\\351\\001");
	/*
	 * ESCAPE_NAP is its own bit, not NP|NA: with NP|NA the printable
	 * (Latin-1) 0xe9 passes through via NP, with NAP it is escaped.
	 */
	CHECK(test, "\xe9", ESCAPE_NP | ESCAPE_NA | ESCAPE_OCTAL, NULL, "\xe9");
	CHECK(test, "\xe9", ESCAPE_NAP | ESCAPE_OCTAL, NULL, "\\351");
	/* NAP without an escaping class: nothing is escaped */
	CHECK(test, "\x01\xe9", ESCAPE_NAP, NULL, "\x01\xe9");
}

/* ---- The @only dictionary ---- */

static void agent_test_only_limits(struct kunit *test)
{
	/* Only characters in @only may be escaped */
	CHECK(test, "\n\t\r", ESCAPE_SPACE, "\n", "\\n\t\r");
	CHECK(test, "abc", ESCAPE_HEX, "b", "a\\x62c");
	/* Chars in @only that are not in a selected class pass as-is */
	CHECK(test, "a\n", ESCAPE_SPACE, "a", "a\n");
	/* Empty @only behaves like NULL */
	CHECK(test, "\n", ESCAPE_SPACE, "", "\\n");
	/* With @only, NP filtering still applies to dictionary members */
	CHECK(test, "a\x01\x02", ESCAPE_NP | ESCAPE_HEX, "a\x01", "a\\x01\x02");
}

static void agent_test_only_nul_not_matched(struct kunit *test)
{
	static const char src[] = "\0a";

	/*
	 * strchr(only, '\0') always matches the terminator, so a NUL byte in
	 * the input is considered "in the dictionary" for any non-empty @only.
	 */
	check_escape(test, src, 2, ESCAPE_NULL, "x", "\\0a", 3);
	check_escape(test, src, 2, ESCAPE_HEX, "x", "\\x00a", 5);
}

static void agent_test_append(struct kunit *test)
{
	/* APPEND: chars in @only are escaped even though printable / ASCII */
	CHECK(test, "abc", ESCAPE_NP | ESCAPE_HEX | ESCAPE_APPEND, "b",
	      "a\\x62c");
	CHECK(test, "abc\x01", ESCAPE_NA | ESCAPE_OCTAL | ESCAPE_APPEND, "c",
	      "ab\\143\x01");
	CHECK(test, "a\x80", ESCAPE_NAP | ESCAPE_HEX | ESCAPE_APPEND, "a",
	      "\\x61\\x80");
	/* APPEND with a character not in any escape class: passes through */
	CHECK(test, "ab", ESCAPE_NP | ESCAPE_SPACE | ESCAPE_APPEND, "a", "ab");
	/* APPEND without @only has no effect */
	CHECK(test, "a\x01", ESCAPE_NP | ESCAPE_HEX | ESCAPE_APPEND, NULL,
	      "a\\x01");
	CHECK(test, "a\x01", ESCAPE_NP | ESCAPE_HEX | ESCAPE_APPEND, "",
	      "a\\x01");
	/* APPEND with @only but no NP/NA: @only does not restrict any more */
	CHECK(test, "\n\t", ESCAPE_SPACE | ESCAPE_APPEND, "\n", "\\n\\t");
}

/* ---- Output boundaries / truncation ---- */

static void agent_test_truncation_single_byte_escape(struct kunit *test)
{
	CHECK_TRUNC(test, "ab", 0, NULL, "ab");
	CHECK_TRUNC(test, "\n", ESCAPE_SPACE, NULL, "\\n");
	CHECK_TRUNC(test, "a\nb", ESCAPE_SPACE, NULL, "a\\nb");
}

static void agent_test_truncation_multi_byte_escape(struct kunit *test)
{
	CHECK_TRUNC(test, "\xff", ESCAPE_OCTAL, NULL, "\\377");
	CHECK_TRUNC(test, "\xff", ESCAPE_HEX, NULL, "\\xff");
	CHECK_TRUNC(test, "\\", ESCAPE_SPECIAL, NULL, "\\\\");
	CHECK_TRUNC(test, "a\x01\x81", ESCAPE_ANY_NP, NULL, "a\\001\\201");
	CHECK_TRUNC(test, "x\x01y\x02", ESCAPE_NP | ESCAPE_HEX, NULL,
		    "x\\x01y\\x02");
}

static void agent_test_truncation_null(struct kunit *test)
{
	static const char src[] = "\0\0";

	check_truncation(test, src, 2, ESCAPE_NULL, NULL, "\\0\\0", 4);
	check_truncation(test, src, 2, ESCAPE_OCTAL, NULL, "\\000\\000", 8);
}

static void agent_test_osz_exact_and_plus_one(struct kunit *test)
{
	char out[16];
	int ret;

	/* osz == ret: fully written, no room for '\0', out[ret] untouched */
	memset(out, POISON, sizeof(out));
	ret = string_escape_mem("\n", 1, out, 2, ESCAPE_SPACE, NULL);
	KUNIT_EXPECT_EQ(test, ret, 2);
	KUNIT_EXPECT_MEMEQ(test, out, "\\n", 2);
	KUNIT_EXPECT_EQ(test, (unsigned char)out[2], POISON);

	/* osz == ret + 1: there is room for a terminator, but none written */
	memset(out, POISON, sizeof(out));
	ret = string_escape_mem("\n", 1, out, 3, ESCAPE_SPACE, NULL);
	KUNIT_EXPECT_EQ(test, ret, 2);
	KUNIT_EXPECT_MEMEQ(test, out, "\\n", 2);
	KUNIT_EXPECT_EQ(test, (unsigned char)out[2], POISON);

	/* osz == ret - 1: one byte short, return still full length */
	memset(out, POISON, sizeof(out));
	ret = string_escape_mem("\n", 1, out, 1, ESCAPE_SPACE, NULL);
	KUNIT_EXPECT_EQ(test, ret, 2);
	KUNIT_EXPECT_EQ(test, out[0], '\\');
	KUNIT_EXPECT_EQ(test, (unsigned char)out[1], POISON);
}

static void agent_test_osz_zero_counts_everything(struct kunit *test)
{
	char out[4];
	int ret;

	memset(out, POISON, sizeof(out));
	ret = string_escape_mem("a\n\x81\0", 4, out, 0, ESCAPE_ANY_NP, NULL);
	/* "a" "\\n" "\\201" "\\0" */
	KUNIT_EXPECT_EQ(test, ret, 1 + 2 + 4 + 2);
	KUNIT_EXPECT_EQ(test, (unsigned char)out[0], POISON);
}

static void agent_test_large_input(struct kunit *test)
{
	char *src, *out;
	int ret, i;
	const int n = 1000;

	src = kunit_kmalloc(test, n, GFP_KERNEL);
	KUNIT_ASSERT_NOT_NULL(test, src);
	out = kunit_kmalloc(test, n * 4 + 1, GFP_KERNEL);
	KUNIT_ASSERT_NOT_NULL(test, out);

	memset(src, 0x81, n);
	memset(out, POISON, n * 4 + 1);
	ret = string_escape_mem(src, n, out, n * 4 + 1, ESCAPE_HEX, NULL);
	KUNIT_ASSERT_EQ(test, ret, n * 4);
	for (i = 0; i < n; i++)
		KUNIT_EXPECT_MEMEQ_MSG(test, out + i * 4, "\\x81", 4, "i=%d", i);
	KUNIT_EXPECT_EQ(test, (unsigned char)out[n * 4], POISON);

	/* Truncate in the middle of an escape sequence */
	memset(out, POISON, n * 4 + 1);
	ret = string_escape_mem(src, n, out, n * 4 - 2, ESCAPE_HEX, NULL);
	KUNIT_EXPECT_EQ(test, ret, n * 4);
	KUNIT_EXPECT_MEMEQ(test, out + (n - 1) * 4, "\\x", 2);
	KUNIT_EXPECT_EQ(test, (unsigned char)out[n * 4 - 2], POISON);
	KUNIT_EXPECT_EQ(test, (unsigned char)out[n * 4 - 1], POISON);
}

static struct kunit_case agent_test_cases[] = {
	KUNIT_CASE(agent_test_no_flags_passthrough),
	KUNIT_CASE(agent_test_zero_length_input),
	KUNIT_CASE(agent_test_space),
	KUNIT_CASE(agent_test_special),
	KUNIT_CASE(agent_test_null),
	KUNIT_CASE(agent_test_octal),
	KUNIT_CASE(agent_test_hex),
	KUNIT_CASE(agent_test_octal_wins_over_hex),
	KUNIT_CASE(agent_test_all_bytes_octal_and_hex),
	KUNIT_CASE(agent_test_precedence),
	KUNIT_CASE(agent_test_np),
	KUNIT_CASE(agent_test_na),
	KUNIT_CASE(agent_test_nap),
	KUNIT_CASE(agent_test_only_limits),
	KUNIT_CASE(agent_test_only_nul_not_matched),
	KUNIT_CASE(agent_test_append),
	KUNIT_CASE(agent_test_truncation_single_byte_escape),
	KUNIT_CASE(agent_test_truncation_multi_byte_escape),
	KUNIT_CASE(agent_test_truncation_null),
	KUNIT_CASE(agent_test_osz_exact_and_plus_one),
	KUNIT_CASE(agent_test_osz_zero_counts_everything),
	KUNIT_CASE(agent_test_large_input),
	{}
};

static struct kunit_suite agent_test_suite = {
	.name = "agent_test",
	.test_cases = agent_test_cases,
};
kunit_test_suite(agent_test_suite);

