// SPDX-License-Identifier: GPL-2.0
/*
 * lib/agent_kunit.c: KUnit test written by an agent for this benchmark.
 * This file is compiled when CONFIG_AGENT_KUNIT_TEST is set.
 *
 * Tests for string_unescape() from lib/string_helpers.c.
 */
#include <kunit/test.h>
#include <linux/string.h>
#include <linux/string_helpers.h>

#define BUF_SZ 64
#define SENTINEL 0x7f

/*
 * Run string_unescape() on a copy of @in into a sentinel-filled buffer and
 * check: return value, exact output bytes (incl. embedded NULs), the trailing
 * NUL, and that nothing past the terminator was touched.
 */
static void check_unescape(struct kunit *test, const char *in,
			   size_t size, unsigned int flags,
			   const char *expected, int exp_len)
{
	char src[BUF_SZ];
	char dst[BUF_SZ];
	int ret, i;

	KUNIT_ASSERT_LT(test, strlen(in), (size_t)BUF_SZ);
	KUNIT_ASSERT_LT(test, exp_len + 1, BUF_SZ);
	strscpy(src, in, BUF_SZ);
	memset(dst, SENTINEL, BUF_SZ);

	ret = string_unescape(src, dst, size, flags);

	KUNIT_EXPECT_EQ_MSG(test, ret, exp_len,
			    "in=\"%s\" size=%zu flags=%#x", in, size, flags);
	KUNIT_EXPECT_MEMEQ_MSG(test, dst, expected, exp_len,
			       "in=\"%s\" size=%zu flags=%#x", in, size, flags);
	KUNIT_EXPECT_EQ_MSG(test, dst[exp_len], '\0',
			    "missing terminator for in=\"%s\"", in);
	for (i = exp_len + 1; i < BUF_SZ; i++)
		KUNIT_EXPECT_EQ_MSG(test, dst[i], (char)SENTINEL,
				    "overwrite at dst[%d] for in=\"%s\"", i, in);
	if (size)
		KUNIT_EXPECT_LT_MSG(test, (size_t)exp_len, size,
				    "wrote more than size for in=\"%s\"", in);
}

/* --- normal inputs ------------------------------------------------------ */

static void agent_test_plain_passthrough(struct kunit *test)
{
	check_unescape(test, "", 0, UNESCAPE_ANY, "", 0);
	check_unescape(test, "a", 0, UNESCAPE_ANY, "a", 1);
	check_unescape(test, "hello world", 0, UNESCAPE_ANY, "hello world", 11);
	/* real control chars pass through untouched */
	check_unescape(test, "a\nb\tc", 0, UNESCAPE_ANY, "a\nb\tc", 5);
	/* no flags: nothing is unescaped */
	check_unescape(test, "\\n\\101\\x41\\a", 0, 0, "\\n\\101\\x41\\a", 12);
}

static void agent_test_space(struct kunit *test)
{
	check_unescape(test, "\\n", 0, UNESCAPE_SPACE, "\n", 1);
	check_unescape(test, "\\r", 0, UNESCAPE_SPACE, "\r", 1);
	check_unescape(test, "\\t", 0, UNESCAPE_SPACE, "\t", 1);
	check_unescape(test, "\\v", 0, UNESCAPE_SPACE, "\v", 1);
	check_unescape(test, "\\f", 0, UNESCAPE_SPACE, "\f", 1);
	check_unescape(test, "a\\nb\\tc\\rd\\ve\\ff", 0, UNESCAPE_SPACE,
		       "a\nb\tc\rd\ve\ff", 11);
	/* space flag alone does not touch other classes */
	check_unescape(test, "\\a\\e\\\"\\\\", 0, UNESCAPE_SPACE,
		       "\\a\\e\\\"\\\\", 8);
	check_unescape(test, "\\101\\x41\\0", 0, UNESCAPE_SPACE,
		       "\\101\\x41\\0", 10);
	/* uppercase is not a space escape */
	check_unescape(test, "\\N\\T", 0, UNESCAPE_SPACE, "\\N\\T", 4);
}

static void agent_test_special(struct kunit *test)
{
	check_unescape(test, "\\\"", 0, UNESCAPE_SPECIAL, "\"", 1);
	check_unescape(test, "\\\\", 0, UNESCAPE_SPECIAL, "\\", 1);
	check_unescape(test, "\\a", 0, UNESCAPE_SPECIAL, "\a", 1);
	check_unescape(test, "\\e", 0, UNESCAPE_SPECIAL, "\x1b", 1);
	check_unescape(test, "x\\\"y\\\\z\\a\\e", 0, UNESCAPE_SPECIAL,
		       "x\"y\\z\a\x1b", 7);
	/* "\\\\n": the double backslash is consumed first, 'n' stays */
	check_unescape(test, "\\\\n", 0, UNESCAPE_ANY, "\\n", 2);
	/* special alone does not touch other classes */
	check_unescape(test, "\\n\\101\\x41", 0, UNESCAPE_SPECIAL,
		       "\\n\\101\\x41", 10);
	/* single quote is not special */
	check_unescape(test, "\\'", 0, UNESCAPE_SPECIAL, "\\'", 2);
}

static void agent_test_octal(struct kunit *test)
{
	check_unescape(test, "\\101", 0, UNESCAPE_OCTAL, "A", 1);
	check_unescape(test, "\\0", 0, UNESCAPE_OCTAL, "\0", 1);
	check_unescape(test, "\\00", 0, UNESCAPE_OCTAL, "\0", 1);
	check_unescape(test, "\\000", 0, UNESCAPE_OCTAL, "\0", 1);
	check_unescape(test, "\\7", 0, UNESCAPE_OCTAL, "\a", 1);
	check_unescape(test, "\\12", 0, UNESCAPE_OCTAL, "\n", 1);
	check_unescape(test, "\\012", 0, UNESCAPE_OCTAL, "\n", 1);
	check_unescape(test, "\\377", 0, UNESCAPE_OCTAL, "\xff", 1);
	check_unescape(test, "\\0101", 0, UNESCAPE_OCTAL, "\x08" "1", 2);
	/* at most three digits */
	check_unescape(test, "\\1234", 0, UNESCAPE_OCTAL, "S4", 2);
	check_unescape(test, "\\1011", 0, UNESCAPE_OCTAL, "A1", 2);
	/* digit terminated by non-digit */
	check_unescape(test, "\\18", 0, UNESCAPE_OCTAL, "\x01" "8", 2);
	check_unescape(test, "\\378", 0, UNESCAPE_OCTAL, "\x1f" "8", 2);
	check_unescape(test, "\\12x", 0, UNESCAPE_OCTAL, "\nx", 2);
	/* first digit 4..7 limits to two digits (value must fit a byte) */
	check_unescape(test, "\\400", 0, UNESCAPE_OCTAL, "\x20" "0", 2);
	check_unescape(test, "\\777", 0, UNESCAPE_OCTAL, "?7", 2);
	check_unescape(test, "\\401", 0, UNESCAPE_OCTAL, " 1", 2);
	/* first digit 0..3 allows three digits */
	check_unescape(test, "\\300", 0, UNESCAPE_OCTAL, "\xc0", 1);
	check_unescape(test, "\\37", 0, UNESCAPE_OCTAL, "\x1f", 1);
	check_unescape(test, "\\40", 0, UNESCAPE_OCTAL, " ", 1);
	/* 8 and 9 are not octal digits */
	check_unescape(test, "\\8", 0, UNESCAPE_OCTAL, "\\8", 2);
	check_unescape(test, "\\9", 0, UNESCAPE_OCTAL, "\\9", 2);
	check_unescape(test, "\\81", 0, UNESCAPE_OCTAL, "\\81", 3);
	/* octal alone does not touch other classes */
	check_unescape(test, "\\n\\x41\\a", 0, UNESCAPE_OCTAL, "\\n\\x41\\a", 8);
	/* multiple in a row */
	check_unescape(test, "\\110\\151\\41", 0, UNESCAPE_OCTAL, "Hi!", 3);
}

static void agent_test_hex(struct kunit *test)
{
	check_unescape(test, "\\x41", 0, UNESCAPE_HEX, "A", 1);
	check_unescape(test, "\\x4", 0, UNESCAPE_HEX, "\x04", 1);
	check_unescape(test, "\\x0", 0, UNESCAPE_HEX, "\0", 1);
	check_unescape(test, "\\x00", 0, UNESCAPE_HEX, "\0", 1);
	check_unescape(test, "\\xff", 0, UNESCAPE_HEX, "\xff", 1);
	check_unescape(test, "\\xFF", 0, UNESCAPE_HEX, "\xff", 1);
	check_unescape(test, "\\xaB", 0, UNESCAPE_HEX, "\xab", 1);
	/* at most two digits */
	check_unescape(test, "\\x414", 0, UNESCAPE_HEX, "A4", 2);
	check_unescape(test, "\\x4142", 0, UNESCAPE_HEX, "A42", 3);
	/* one digit followed by non-hex */
	check_unescape(test, "\\x4g", 0, UNESCAPE_HEX, "\x04g", 2);
	check_unescape(test, "\\xa ", 0, UNESCAPE_HEX, "\x0a ", 2);
	/* no digits: left alone */
	check_unescape(test, "\\x", 0, UNESCAPE_HEX, "\\x", 2);
	check_unescape(test, "\\xg", 0, UNESCAPE_HEX, "\\xg", 3);
	check_unescape(test, "\\xG1", 0, UNESCAPE_HEX, "\\xG1", 4);
	/* uppercase X is not a hex escape */
	check_unescape(test, "\\X41", 0, UNESCAPE_HEX, "\\X41", 4);
	/* hex alone does not touch other classes */
	check_unescape(test, "\\n\\101\\a", 0, UNESCAPE_HEX, "\\n\\101\\a", 8);
	check_unescape(test, "\\x48\\x69\\x21", 0, UNESCAPE_HEX, "Hi!", 3);
}

static void agent_test_any_mixed(struct kunit *test)
{
	check_unescape(test, "\\n\\101\\x41\\a\\\\\\\"\\e", 0, UNESCAPE_ANY,
		       "\nAA\a\\\"\x1b", 7);
	check_unescape(test, "foo\\tbar\\n", 0, UNESCAPE_ANY, "foo\tbar\n", 8);
	/* flag combinations */
	check_unescape(test, "\\n\\101\\x41\\a", 0,
		       UNESCAPE_SPACE | UNESCAPE_OCTAL, "\nA\\x41\\a", 8);
	check_unescape(test, "\\n\\101\\x41\\a", 0,
		       UNESCAPE_HEX | UNESCAPE_SPECIAL, "\\n\\101A\a", 8);
	/* \\0 under ANY is octal NUL; following digits still handled */
	check_unescape(test, "\\0", 0, UNESCAPE_ANY, "\0", 1);
	check_unescape(test, "a\\0b", 0, UNESCAPE_ANY, "a\0b", 3);
	/* unknown escapes are preserved verbatim under ANY */
	check_unescape(test, "\\q", 0, UNESCAPE_ANY, "\\q", 2);
	check_unescape(test, "\\8", 0, UNESCAPE_ANY, "\\8", 2);
	check_unescape(test, "\\x", 0, UNESCAPE_ANY, "\\x", 2);
	check_unescape(test, "\\xz", 0, UNESCAPE_ANY, "\\xz", 3);
	check_unescape(test, "\\ ", 0, UNESCAPE_ANY, "\\ ", 2);
	check_unescape(test, "a\\qb", 0, UNESCAPE_ANY, "a\\qb", 4);
}

/* --- boundaries --------------------------------------------------------- */

static void agent_test_trailing_backslash(struct kunit *test)
{
	check_unescape(test, "\\", 0, UNESCAPE_ANY, "\\", 1);
	check_unescape(test, "abc\\", 0, UNESCAPE_ANY, "abc\\", 4);
	/* three backslashes: one pair + one trailing */
	check_unescape(test, "\\\\\\", 0, UNESCAPE_ANY, "\\\\", 2);
	/* trailing backslash with an escape before it */
	check_unescape(test, "\\n\\", 0, UNESCAPE_ANY, "\n\\", 2);
	/* without SPECIAL a pair stays as pair, then trailing */
	check_unescape(test, "\\\\\\", 0, UNESCAPE_SPACE, "\\\\\\", 3);
}

static void agent_test_size_truncation(struct kunit *test)
{
	/* size==1: room for terminator only */
	check_unescape(test, "hello", 1, UNESCAPE_ANY, "", 0);
	check_unescape(test, "", 1, UNESCAPE_ANY, "", 0);
	/* size N writes at most N-1 characters */
	check_unescape(test, "hello", 2, UNESCAPE_ANY, "h", 1);
	check_unescape(test, "hello", 3, UNESCAPE_ANY, "he", 2);
	check_unescape(test, "hello", 5, UNESCAPE_ANY, "hell", 4);
	/* exact fit */
	check_unescape(test, "hello", 6, UNESCAPE_ANY, "hello", 5);
	/* more than enough */
	check_unescape(test, "hello", 7, UNESCAPE_ANY, "hello", 5);
	check_unescape(test, "hello", 60, UNESCAPE_ANY, "hello", 5);
}

static void agent_test_size_escape_boundary(struct kunit *test)
{
	/*
	 * An escape needs room: when only one output slot remains before the
	 * terminator, the backslash is copied literally and the escaped
	 * character is dropped.
	 */
	check_unescape(test, "\\n", 2, UNESCAPE_ANY, "\\", 1);
	check_unescape(test, "\\n", 3, UNESCAPE_ANY, "\n", 1);
	check_unescape(test, "\\n", 4, UNESCAPE_ANY, "\n", 1);

	check_unescape(test, "a\\nb", 2, UNESCAPE_ANY, "a", 1);
	check_unescape(test, "a\\nb", 3, UNESCAPE_ANY, "a\\", 2);
	check_unescape(test, "a\\nb", 4, UNESCAPE_ANY, "a\n", 2);
	check_unescape(test, "a\\nb", 5, UNESCAPE_ANY, "a\nb", 3);
	check_unescape(test, "a\\nb", 6, UNESCAPE_ANY, "a\nb", 3);

	/* multi-char escapes at the boundary */
	check_unescape(test, "\\101", 2, UNESCAPE_ANY, "\\", 1);
	check_unescape(test, "\\101", 3, UNESCAPE_ANY, "A", 1);
	check_unescape(test, "\\x41", 2, UNESCAPE_ANY, "\\", 1);
	check_unescape(test, "\\x41", 3, UNESCAPE_ANY, "A", 1);
	check_unescape(test, "\\x41\\x42", 3, UNESCAPE_ANY, "A", 1);
	check_unescape(test, "\\x41\\x42", 4, UNESCAPE_ANY, "A\\", 2);
	check_unescape(test, "\\x41\\x42", 5, UNESCAPE_ANY, "AB", 2);

	/* trailing backslash with a tight buffer */
	check_unescape(test, "a\\", 2, UNESCAPE_ANY, "a", 1);
	check_unescape(test, "a\\", 3, UNESCAPE_ANY, "a\\", 2);

	/* unknown escape with a tight buffer */
	check_unescape(test, "\\q", 2, UNESCAPE_ANY, "\\", 1);
	check_unescape(test, "\\q", 3, UNESCAPE_ANY, "\\q", 2);
}

static void agent_test_in_place(struct kunit *test)
{
	char buf[BUF_SZ];
	int ret;

	strscpy(buf, "a\\tb\\x41\\101\\\\", BUF_SZ);
	ret = string_unescape(buf, buf, 0, UNESCAPE_ANY);
	KUNIT_EXPECT_EQ(test, ret, 6);
	KUNIT_EXPECT_STREQ(test, buf, "a\tbAA\\");

	/*
	 * In place with a size smaller than the input: with 5 only one slot
	 * is left when the escape is reached, so the backslash is literal.
	 */
	strscpy(buf, "abc\\ndef", BUF_SZ);
	ret = string_unescape(buf, buf, 5, UNESCAPE_ANY);
	KUNIT_EXPECT_EQ(test, ret, 4);
	KUNIT_EXPECT_STREQ(test, buf, "abc\\");

	strscpy(buf, "abc\\ndef", BUF_SZ);
	ret = string_unescape(buf, buf, 6, UNESCAPE_ANY);
	KUNIT_EXPECT_EQ(test, ret, 4);
	KUNIT_EXPECT_STREQ(test, buf, "abc\n");
}

static void agent_test_dst_terminated_without_size(struct kunit *test)
{
	char dst[8];
	int ret;

	memset(dst, SENTINEL, sizeof(dst));
	ret = string_unescape("ab", dst, 0, UNESCAPE_ANY);
	KUNIT_EXPECT_EQ(test, ret, 2);
	KUNIT_EXPECT_EQ(test, dst[0], 'a');
	KUNIT_EXPECT_EQ(test, dst[1], 'b');
	KUNIT_EXPECT_EQ(test, dst[2], '\0');
	KUNIT_EXPECT_EQ(test, dst[3], (char)SENTINEL);
}

static struct kunit_case agent_test_cases[] = {
	KUNIT_CASE(agent_test_plain_passthrough),
	KUNIT_CASE(agent_test_space),
	KUNIT_CASE(agent_test_special),
	KUNIT_CASE(agent_test_octal),
	KUNIT_CASE(agent_test_hex),
	KUNIT_CASE(agent_test_any_mixed),
	KUNIT_CASE(agent_test_trailing_backslash),
	KUNIT_CASE(agent_test_size_truncation),
	KUNIT_CASE(agent_test_size_escape_boundary),
	KUNIT_CASE(agent_test_in_place),
	KUNIT_CASE(agent_test_dst_terminated_without_size),
	{}
};

static struct kunit_suite agent_test_suite = {
	.name = "agent_test",
	.test_cases = agent_test_cases,
};

kunit_test_suite(agent_test_suite);

