/*
 * lib/agent_kunit.c: KUnit test written by an agent for this benchmark.
 * This file is compiled when CONFIG_AGENT_KUNIT_TEST is set.
 *
 * Tests for get_option() in lib/cmdline.c.
 */

#include <kunit/test.h>
#include <linux/kernel.h>
#include <linux/string.h>

#define SENTINEL 0x5a5a5a5a

/*
 * Helper: run get_option() on a copy of @in, check return value, parsed
 * integer and how far the cursor advanced (@consumed bytes).
 */
static void check_option(struct kunit *test, const char *in, int exp_ret,
			 int exp_val, size_t consumed)
{
	char buf[64];
	char *cur = buf;
	int val = SENTINEL;
	int ret;

	KUNIT_ASSERT_LT(test, strlen(in), sizeof(buf));
	strscpy(buf, in, sizeof(buf));

	ret = get_option(&cur, &val);
	KUNIT_EXPECT_EQ_MSG(test, ret, exp_ret, "input \"%s\"", in);
	KUNIT_EXPECT_EQ_MSG(test, val, exp_val, "input \"%s\"", in);
	KUNIT_EXPECT_PTR_EQ_MSG(test, cur, buf + consumed, "input \"%s\"", in);
}

/* Return code 1: plain integers, cursor at terminating NUL. */
static void get_option_simple_test(struct kunit *test)
{
	check_option(test, "0", 1, 0, 1);
	check_option(test, "1", 1, 1, 1);
	check_option(test, "9", 1, 9, 1);
	check_option(test, "10", 1, 10, 2);
	check_option(test, "42", 1, 42, 2);
	check_option(test, "12345", 1, 12345, 5);
	check_option(test, "007", 1, 7, 3);
}

/* Negative numbers via leading hyphen. */
static void get_option_negative_test(struct kunit *test)
{
	check_option(test, "-1", 1, -1, 2);
	check_option(test, "-0", 1, 0, 2);
	check_option(test, "-42", 1, -42, 3);
	check_option(test, "-42,", 2, -42, 4);
	check_option(test, "-5-", 3, -5, 2);
	check_option(test, "-0x10", 1, -16, 5);
}

/* Return code 2: integer followed by comma; comma is consumed. */
static void get_option_comma_test(struct kunit *test)
{
	check_option(test, "1,", 2, 1, 2);
	check_option(test, "1,2", 2, 1, 2);
	check_option(test, "123,456", 2, 123, 4);
	check_option(test, "0,", 2, 0, 2);
	check_option(test, "7,,", 2, 7, 2);
}

/* Return code 3: integer followed by hyphen; hyphen is NOT consumed. */
static void get_option_range_test(struct kunit *test)
{
	check_option(test, "1-", 3, 1, 1);
	check_option(test, "1-5", 3, 1, 1);
	check_option(test, "10-20,", 3, 10, 2);
	check_option(test, "0-0", 3, 0, 1);
}

/* Hex and octal prefixes are accepted (base 0). */
static void get_option_bases_test(struct kunit *test)
{
	check_option(test, "0x10", 1, 16, 4);
	check_option(test, "0X1f", 1, 31, 4);
	check_option(test, "0xff,", 2, 255, 5);
	check_option(test, "010", 1, 8, 3);
	check_option(test, "0x", 1, 0, 1);	/* only the "0" parses */
	check_option(test, "0b", 1, 0, 1);
	check_option(test, "0o17", 1, 0, 1);
}

/* Integer limits and wrap-around through the unsigned long long path. */
static void get_option_limits_test(struct kunit *test)
{
	check_option(test, "2147483647", 1, INT_MAX, 10);
	check_option(test, "-2147483648", 1, INT_MIN, 11);
	check_option(test, "4294967295", 1, -1, 10);
	check_option(test, "0x7fffffff", 1, INT_MAX, 10);
	check_option(test, "0xffffffff", 1, -1, 10);
}

/* Return code 0: no integer at all. pint must remain untouched. */
static void get_option_no_int_test(struct kunit *test)
{
	check_option(test, "", 0, SENTINEL, 0);
	check_option(test, "abc", 0, 0, 0);
	check_option(test, ",", 0, 0, 0);
	check_option(test, ",1", 0, 0, 0);
	check_option(test, " 1", 0, 0, 0);
	check_option(test, "+1", 0, 0, 0);
	check_option(test, "x1", 0, 0, 0);
}

/* Leading hyphen without digits: no int, but the hyphen is consumed. */
static void get_option_lone_hyphen_test(struct kunit *test)
{
	check_option(test, "-", 0, 0, 1);
	check_option(test, "-,", 0, 0, 1);
	check_option(test, "-abc", 0, 0, 1);
	check_option(test, "--1", 0, 0, 1);
	check_option(test, "-x1", 0, 0, 1);
}

/* Trailing garbage: int found, cursor stops at the first non-digit. */
static void get_option_trailing_test(struct kunit *test)
{
	check_option(test, "1a", 1, 1, 1);
	check_option(test, "12 ", 1, 12, 2);
	check_option(test, "12;3", 1, 12, 2);
	check_option(test, "3=4", 1, 3, 1);
	check_option(test, "1x2", 1, 1, 1);
}

/* NULL string pointer and NULL output pointer. */
static void get_option_null_test(struct kunit *test)
{
	char buf[] = "1,";
	char *cur = NULL;
	int val = SENTINEL;

	KUNIT_EXPECT_EQ(test, get_option(&cur, &val), 0);
	KUNIT_EXPECT_EQ(test, val, SENTINEL);
	KUNIT_EXPECT_NULL(test, cur);

	/* pint == NULL acts as validator; cursor still advances. */
	cur = buf;
	KUNIT_EXPECT_EQ(test, get_option(&cur, NULL), 2);
	KUNIT_EXPECT_PTR_EQ(test, cur, buf + 2);
	KUNIT_EXPECT_EQ(test, get_option(&cur, NULL), 0);
	KUNIT_EXPECT_PTR_EQ(test, cur, buf + 2);
}

/* Repeated calls walk a comma-separated list exactly. */
static void get_option_sequence_test(struct kunit *test)
{
	char buf[] = "1,22,-3,0x4,5-7,8";
	char *cur = buf;
	int val = SENTINEL;

	KUNIT_EXPECT_EQ(test, get_option(&cur, &val), 2);
	KUNIT_EXPECT_EQ(test, val, 1);
	KUNIT_EXPECT_EQ(test, get_option(&cur, &val), 2);
	KUNIT_EXPECT_EQ(test, val, 22);
	KUNIT_EXPECT_EQ(test, get_option(&cur, &val), 2);
	KUNIT_EXPECT_EQ(test, val, -3);
	KUNIT_EXPECT_EQ(test, get_option(&cur, &val), 2);
	KUNIT_EXPECT_EQ(test, val, 4);
	KUNIT_EXPECT_EQ(test, get_option(&cur, &val), 3);
	KUNIT_EXPECT_EQ(test, val, 5);
	KUNIT_EXPECT_PTR_EQ(test, cur, buf + 13);
	KUNIT_EXPECT_EQ(test, *cur, '-');

	/* Re-reading from the hyphen parses "-7," as a negative number. */
	KUNIT_EXPECT_EQ(test, get_option(&cur, &val), 2);
	KUNIT_EXPECT_EQ(test, val, -7);
	KUNIT_EXPECT_PTR_EQ(test, cur, buf + 16);
	KUNIT_EXPECT_EQ(test, get_option(&cur, &val), 1);
	KUNIT_EXPECT_EQ(test, val, 8);
	KUNIT_EXPECT_PTR_EQ(test, cur, buf + strlen(buf));
	KUNIT_EXPECT_EQ(test, get_option(&cur, &val), 0);
	KUNIT_EXPECT_EQ(test, val, 8);
	KUNIT_EXPECT_PTR_EQ(test, cur, buf + strlen(buf));
}

static struct kunit_case agent_test_cases[] = {
	KUNIT_CASE(get_option_simple_test),
	KUNIT_CASE(get_option_negative_test),
	KUNIT_CASE(get_option_comma_test),
	KUNIT_CASE(get_option_range_test),
	KUNIT_CASE(get_option_bases_test),
	KUNIT_CASE(get_option_limits_test),
	KUNIT_CASE(get_option_no_int_test),
	KUNIT_CASE(get_option_lone_hyphen_test),
	KUNIT_CASE(get_option_trailing_test),
	KUNIT_CASE(get_option_null_test),
	KUNIT_CASE(get_option_sequence_test),
	{}
};

static struct kunit_suite agent_test_suite = {
	.name = "agent_test",
	.test_cases = agent_test_cases,
};

kunit_test_suite(agent_test_suite);

