// SPDX-License-Identifier: GPL-2.0
/*
 * lib/agent_kunit.c: KUnit test written by an agent for this benchmark.
 * This file is compiled when CONFIG_AGENT_KUNIT_TEST is set.
 *
 * Test suite for get_options() from lib/cmdline.c.
 */

#include <kunit/test.h>
#include <linux/kernel.h>
#include <linux/string.h>

#define SENTINEL	0x5a5a5a5a
#define ARR_MAX		16

/* Fill the array with a sentinel so untouched slots can be verified. */
static void fill_sentinel(int *ints, int n)
{
	int i;

	for (i = 0; i < n; i++)
		ints[i] = SENTINEL;
}

/*
 * Run get_options() and check the returned pointer offset, the count in
 * ints[0], and the parsed values. Slots after the last expected value, up
 * to @untouched_until, must still hold the sentinel.
 */
static void check_options(struct kunit *test, const char *str, int nints,
			  size_t expect_off, int expect_count,
			  const int *expect_vals, int nvals, int untouched_until)
{
	int ints[ARR_MAX];
	char *end;
	int i;

	fill_sentinel(ints, ARR_MAX);
	end = get_options(str, nints, ints);

	KUNIT_EXPECT_PTR_EQ_MSG(test, end, (char *)str + expect_off,
				"str=\"%s\" nints=%d: end offset %zd, expected %zu",
				str, nints, (ssize_t)(end - str), expect_off);
	KUNIT_EXPECT_EQ_MSG(test, ints[0], expect_count,
			    "str=\"%s\" nints=%d: wrong count", str, nints);
	for (i = 0; i < nvals; i++)
		KUNIT_EXPECT_EQ_MSG(test, ints[i + 1], expect_vals[i],
				    "str=\"%s\" nints=%d: ints[%d]", str, nints, i + 1);
	for (i = nvals + 1; i < untouched_until; i++)
		KUNIT_EXPECT_EQ_MSG(test, ints[i], SENTINEL,
				    "str=\"%s\" nints=%d: ints[%d] clobbered", str, nints, i);
}

/* ---- normal inputs ---- */

static void agent_single_int(struct kunit *test)
{
	static const int v[] = { 42 };

	check_options(test, "42", 4, 2, 1, v, 1, 4);
}

static void agent_zero_value(struct kunit *test)
{
	static const int v[] = { 0 };

	check_options(test, "0", 4, 1, 1, v, 1, 4);
}

