/* ---- boundaries: array capacity ---- */

static void agent_array_exactly_full(struct kunit *test)
{
	static const int v[] = { 1, 2, 3 };

	/* nints=4 leaves room for exactly three values. */
	check_options(test, "1,2,3", 4, 5, 3, v, 3, 4);
}

static void agent_array_overflow_stops(struct kunit *test)
{
	static const int v[] = { 1, 2 };
	int ints[ARR_MAX];
	char *end;

	/* Only two slots: parse halts, pointer left at the third number. */
	check_options(test, "1,2,3,4", 3, 4, 2, v, 2, 3);

	/* Direct check that slots beyond nints are never written. */
	fill_sentinel(ints, ARR_MAX);
	end = get_options("1,2,3,4", 3, ints);
	KUNIT_EXPECT_STREQ(test, end, "3,4");
	KUNIT_EXPECT_EQ(test, ints[3], SENTINEL);
	KUNIT_EXPECT_EQ(test, ints[4], SENTINEL);
}

static void agent_nints_one_parses_nothing(struct kunit *test)
