	fill_sentinel(ints, ARR_MAX);
	end = get_options(s, 1, ints);
	KUNIT_EXPECT_PTR_EQ(test, end, (char *)s);
	KUNIT_EXPECT_EQ(test, ints[0], 0);
	KUNIT_EXPECT_EQ(test, ints[1], SENTINEL);
}

static void agent_range_exactly_fits(struct kunit *test)
