	check_options(test, "1-3", 4, 3, 3, v, 3, 4);
}

static void agent_range_truncated_by_capacity(struct kunit *test)
{
	int ints[ARR_MAX];
	char *end;

	/*
	 * Three slots for a 10-element range: only 1,2,3 are stored and the
	 * pointer is left at the upper bound. The reported count reflects
	 * the full range (current behaviour).
	 */
	fill_sentinel(ints, ARR_MAX);
	end = get_options("1-10", 4, ints);
	KUNIT_EXPECT_STREQ(test, end, "10");
	KUNIT_EXPECT_EQ(test, ints[0], 9);
	KUNIT_EXPECT_EQ(test, ints[1], 1);
	KUNIT_EXPECT_EQ(test, ints[2], 2);
	KUNIT_EXPECT_EQ(test, ints[3], 3);
	KUNIT_EXPECT_EQ(test, ints[4], SENTINEL);

	/* One short of fitting: upper bound is not stored. */
	fill_sentinel(ints, ARR_MAX);
	end = get_options("1-3", 3, ints);
	KUNIT_EXPECT_STREQ(test, end, "3");
	KUNIT_EXPECT_EQ(test, ints[0], 2);
	KUNIT_EXPECT_EQ(test, ints[1], 1);
	KUNIT_EXPECT_EQ(test, ints[2], 2);
	KUNIT_EXPECT_EQ(test, ints[3], SENTINEL);
}

/* ---- validation mode (nints == 0) ---- */

static void agent_validate_list(struct kunit *test)
{
	const char *s = "1,2,3";
	int ints[ARR_MAX];
	char *end;

	fill_sentinel(ints, ARR_MAX);
	end = get_options(s, 0, ints);
	KUNIT_EXPECT_PTR_EQ(test, end, (char *)s + 5);
	KUNIT_EXPECT_EQ(test, ints[0], 3);
	KUNIT_EXPECT_EQ(test, ints[1], SENTINEL);
