static void agent_validate_range(struct kunit *test)
{
	int ints[ARR_MAX];
	char *end;

	fill_sentinel(ints, ARR_MAX);
	end = get_options("1-10", 0, ints);
	KUNIT_EXPECT_STREQ(test, end, "");
	KUNIT_EXPECT_EQ(test, ints[0], 10);
	KUNIT_EXPECT_EQ(test, ints[1], SENTINEL);

	fill_sentinel(ints, ARR_MAX);
