static void agent_validate_errors(struct kunit *test)
{
	int ints[ARR_MAX];
	char *end;

	fill_sentinel(ints, ARR_MAX);
	end = get_options("", 0, ints);
	KUNIT_EXPECT_STREQ(test, end, "");
	KUNIT_EXPECT_EQ(test, ints[0], 0);

	fill_sentinel(ints, ARR_MAX);
	end = get_options("1,2,x", 0, ints);
	KUNIT_EXPECT_STREQ(test, end, "x");
	KUNIT_EXPECT_EQ(test, ints[0], 2);
	KUNIT_EXPECT_EQ(test, ints[1], SENTINEL);

	fill_sentinel(ints, ARR_MAX);
	end = get_options("5-3", 0, ints);
	KUNIT_EXPECT_STREQ(test, end, "3");
	KUNIT_EXPECT_EQ(test, ints[0], 0);
}

/* ---- error paths ---- */

static void agent_empty_string(struct kunit *test)
{
	const char *s = "";
	int ints[ARR_MAX];
	char *end;

	fill_sentinel(ints, ARR_MAX);
	end = get_options(s, 4, ints);
	KUNIT_EXPECT_PTR_EQ(test, end, (char *)s);
	KUNIT_EXPECT_EQ(test, ints[0], 0);
	KUNIT_EXPECT_EQ(test, ints[1], SENTINEL);
}

static void agent_non_numeric(struct kunit *test)
{
	const char *s = "abc";
	int ints[ARR_MAX];
	char *end;

	fill_sentinel(ints, ARR_MAX);
	end = get_options(s, 4, ints);
	KUNIT_EXPECT_PTR_EQ(test, end, (char *)s);
	KUNIT_EXPECT_EQ(test, ints[0], 0);
}

static void agent_garbage_after_int(struct kunit *test)
{
	static const int v[] = { 1 };

	/* Parse stops at the first non-separator character. */
	check_options(test, "1x", 4, 1, 1, v, 1, 4);
	check_options(test, "1 2", 4, 1, 1, v, 1, 4);
	check_options(test, "1;2", 4, 1, 1, v, 1, 4);
}

/*
 * A failed parse after a comma still stores 0 into the slot it was aimed
 * at (get_option() writes *pint before deciding there was no integer),
 * but the count excludes it and later slots stay untouched.
 */
static void agent_garbage_in_list(struct kunit *test)
{
	static const int v[] = { 1, 2 };
	int ints[ARR_MAX];
	char *end;

	/* Comma consumed, then "abc" fails: pointer rests on 'a'. */
	check_options(test, "1,2,abc", 8, 4, 2, v, 2, 3);

	fill_sentinel(ints, ARR_MAX);
	end = get_options("1,2,abc", 8, ints);
	KUNIT_EXPECT_STREQ(test, end, "abc");
	KUNIT_EXPECT_EQ(test, ints[0], 2);
	KUNIT_EXPECT_EQ(test, ints[3], 0);
	KUNIT_EXPECT_EQ(test, ints[4], SENTINEL);
}

static void agent_trailing_comma(struct kunit *test)
{
	static const int v[] = { 1, 2 };

	check_options(test, "1,2,", 8, 4, 2, v, 2, 8);
}

static void agent_double_comma(struct kunit *test)
{
	static const int v[] = { 1 };

	/* Second comma is not a number: stop at it. */
	check_options(test, "1,,2", 8, 2, 1, v, 1, 2);
}

static void agent_leading_comma(struct kunit *test)
{
	const char *s = ",1";
	int ints[ARR_MAX];
	char *end;

	fill_sentinel(ints, ARR_MAX);
	end = get_options(s, 4, ints);
	KUNIT_EXPECT_PTR_EQ(test, end, (char *)s);
	KUNIT_EXPECT_EQ(test, ints[0], 0);
}

static void agent_space_after_comma(struct kunit *test)
{
	static const int v[] = { 1 };

	/* No whitespace skipping: " 2" is not a number. */
	check_options(test, "1, 2", 4, 2, 1, v, 1, 2);
}

static void agent_lone_hyphen(struct kunit *test)
{
	const char *s = "-";
	int ints[ARR_MAX];
	char *end;

	/* A leading hyphen with no digits is consumed but yields nothing. */
	fill_sentinel(ints, ARR_MAX);
	end = get_options(s, 4, ints);
	KUNIT_EXPECT_PTR_EQ(test, end, (char *)s + 1);
	KUNIT_EXPECT_EQ(test, ints[0], 0);

	s = "-,5";
	fill_sentinel(ints, ARR_MAX);
	end = get_options(s, 4, ints);
	KUNIT_EXPECT_PTR_EQ(test, end, (char *)s + 1);
	KUNIT_EXPECT_EQ(test, ints[0], 0);
}

static void agent_reversed_range(struct kunit *test)
{
	int ints[ARR_MAX];
	char *end;

	/* Upper bound lower than start: parse aborts with no values. */
	fill_sentinel(ints, ARR_MAX);
	end = get_options("5-3", 8, ints);
	KUNIT_EXPECT_STREQ(test, end, "3");
	KUNIT_EXPECT_EQ(test, ints[0], 0);
	KUNIT_EXPECT_EQ(test, ints[2], SENTINEL);

	/* Earlier values survive; count covers only them. */
	fill_sentinel(ints, ARR_MAX);
	end = get_options("1,5-3,9", 8, ints);
	KUNIT_EXPECT_STREQ(test, end, "3,9");
	KUNIT_EXPECT_EQ(test, ints[0], 1);
	KUNIT_EXPECT_EQ(test, ints[1], 1);
	KUNIT_EXPECT_EQ(test, ints[3], SENTINEL);
}

static void agent_range_missing_upper(struct kunit *test)
{
	int ints[ARR_MAX];
	char *end;

	/* "4-" parses upper bound as 0, i.e. a reversed range. */
	fill_sentinel(ints, ARR_MAX);
	end = get_options("4-", 8, ints);
	KUNIT_EXPECT_STREQ(test, end, "");
	KUNIT_EXPECT_EQ(test, ints[0], 0);

	/* "0-" is a degenerate range 0-0 followed by nothing. */
	fill_sentinel(ints, ARR_MAX);
	end = get_options("0-", 8, ints);
	KUNIT_EXPECT_STREQ(test, end, "");
	KUNIT_EXPECT_EQ(test, ints[0], 0);

	/* "4-x": same as missing upper bound, pointer rests on 'x'. */
	fill_sentinel(ints, ARR_MAX);
	end = get_options("4-x", 8, ints);
	KUNIT_EXPECT_STREQ(test, end, "x");
	KUNIT_EXPECT_EQ(test, ints[0], 0);
}

static void agent_range_negative_upper(struct kunit *test)
{
	int ints[ARR_MAX];
	char *end;

	/* "1--3": upper bound -3 < 1, parse aborts. */
	fill_sentinel(ints, ARR_MAX);
	end = get_options("1--3", 8, ints);
	KUNIT_EXPECT_STREQ(test, end, "-3");
	KUNIT_EXPECT_EQ(test, ints[0], 0);
}

static void agent_range_garbage_after_upper(struct kunit *test)
{
	static const int v[] = { 1, 2, 3 };

	/* Range completes, then 'z' ends the parse. */
	check_options(test, "1-3z", 8, 3, 3, v, 3, 8);
}

static struct kunit_case agent_test_cases[] = {
	KUNIT_CASE(agent_single_int),
	KUNIT_CASE(agent_zero_value),
	KUNIT_CASE(agent_comma_list),
	KUNIT_CASE(agent_negative_values),
	KUNIT_CASE(agent_hex_and_octal),
	KUNIT_CASE(agent_large_values),
	KUNIT_CASE(agent_simple_range),
	KUNIT_CASE(agent_range_from_zero),
	KUNIT_CASE(agent_range_then_list),
	KUNIT_CASE(agent_list_then_range),
	KUNIT_CASE(agent_two_ranges),
	KUNIT_CASE(agent_range_hex_bounds),
	KUNIT_CASE(agent_degenerate_range),
	KUNIT_CASE(agent_adjacent_range),
	KUNIT_CASE(agent_array_exactly_full),
	KUNIT_CASE(agent_array_overflow_stops),
	KUNIT_CASE(agent_nints_one_parses_nothing),
	KUNIT_CASE(agent_range_exactly_fits),
	KUNIT_CASE(agent_range_truncated_by_capacity),
	KUNIT_CASE(agent_validate_list),
	KUNIT_CASE(agent_validate_range),
	KUNIT_CASE(agent_validate_errors),
	KUNIT_CASE(agent_empty_string),
	KUNIT_CASE(agent_non_numeric),
	KUNIT_CASE(agent_garbage_after_int),
	KUNIT_CASE(agent_garbage_in_list),
	KUNIT_CASE(agent_trailing_comma),
	KUNIT_CASE(agent_double_comma),
	KUNIT_CASE(agent_leading_comma),
	KUNIT_CASE(agent_space_after_comma),
	KUNIT_CASE(agent_lone_hyphen),
