/*
 * lib/agent_kunit.c: KUnit test written by an agent for this benchmark.
 * This file is compiled when CONFIG_AGENT_KUNIT_TEST is set.
 *
 * Tests for memparse() in lib/cmdline.c.
 */
#include <kunit/test.h>
#include <linux/kernel.h>
#include <linux/string.h>

#define KB (1ULL << 10)
#define MB (1ULL << 20)
#define GB (1ULL << 30)
#define TB (1ULL << 40)
#define PB (1ULL << 50)
#define EB (1ULL << 60)

/*
 * Parse @str, check the value and the offset (in chars from the start of
 * @str) at which parsing stopped.
 */
static void check_memparse(struct kunit *test, const char *str,
			   unsigned long long want, size_t want_off)
{
	char *end = NULL;
	unsigned long long got;

	got = memparse(str, &end);
	KUNIT_EXPECT_EQ_MSG(test, got, want, "memparse(\"%s\") value", str);
	KUNIT_ASSERT_NOT_NULL_MSG(test, end, "memparse(\"%s\") end pointer", str);
	KUNIT_EXPECT_PTR_EQ_MSG(test, (const char *)end, str + want_off,
				"memparse(\"%s\") end offset: got %zd want %zu",
				str, (ssize_t)(end - str), want_off);
}

static void memparse_plain_decimal(struct kunit *test)
{
	check_memparse(test, "0", 0, 1);
	check_memparse(test, "1", 1, 1);
	check_memparse(test, "9", 9, 1);
	check_memparse(test, "10", 10, 2);
	check_memparse(test, "42", 42, 2);
	check_memparse(test, "1023", 1023, 4);
	check_memparse(test, "1024", 1024, 4);
	check_memparse(test, "1025", 1025, 4);
	check_memparse(test, "4294967295", 4294967295ULL, 10);
	check_memparse(test, "4294967296", 4294967296ULL, 10);
	check_memparse(test, "18446744073709551615", ULLONG_MAX, 20);
}

static void memparse_kilo(struct kunit *test)
{
	check_memparse(test, "1k", KB, 2);
	check_memparse(test, "1K", KB, 2);
	check_memparse(test, "0k", 0, 2);
	check_memparse(test, "2K", 2 * KB, 2);
	check_memparse(test, "3k", 3 * KB, 2);
	check_memparse(test, "1023k", 1023 * KB, 5);
	check_memparse(test, "1024k", MB, 5);
	check_memparse(test, "1025k", 1025 * KB, 5);
}

static void memparse_mega(struct kunit *test)
{
	check_memparse(test, "1m", MB, 2);
	check_memparse(test, "1M", MB, 2);
	check_memparse(test, "0M", 0, 2);
	check_memparse(test, "7m", 7 * MB, 2);
	check_memparse(test, "1024M", GB, 5);
	check_memparse(test, "3000M", 3000 * MB, 5);
}

static void memparse_giga(struct kunit *test)
{
	check_memparse(test, "1g", GB, 2);
	check_memparse(test, "1G", GB, 2);
	check_memparse(test, "0g", 0, 2);
	check_memparse(test, "5G", 5 * GB, 2);
	check_memparse(test, "1024G", TB, 5);
}

static void memparse_tera(struct kunit *test)
{
	check_memparse(test, "1t", TB, 2);
	check_memparse(test, "1T", TB, 2);
	check_memparse(test, "0T", 0, 2);
	check_memparse(test, "2T", 2 * TB, 2);
	check_memparse(test, "1024T", PB, 5);
}

static void memparse_peta(struct kunit *test)
{
	check_memparse(test, "1p", PB, 2);
	check_memparse(test, "1P", PB, 2);
	check_memparse(test, "0p", 0, 2);
	check_memparse(test, "9P", 9 * PB, 2);
	check_memparse(test, "1024P", EB, 5);
}

static void memparse_exa(struct kunit *test)
{
	check_memparse(test, "1e", EB, 2);
	check_memparse(test, "1E", EB, 2);
	check_memparse(test, "0E", 0, 2);
	check_memparse(test, "15E", 15 * EB, 3);
}

/* Each suffix must be exactly 1024x the one below it. */
static void memparse_suffix_ladder(struct kunit *test)
{
	char *end;

	KUNIT_EXPECT_EQ(test, memparse("1k", &end), 1024 * memparse("1", &end));
	KUNIT_EXPECT_EQ(test, memparse("1m", &end), 1024 * memparse("1k", &end));
	KUNIT_EXPECT_EQ(test, memparse("1g", &end), 1024 * memparse("1m", &end));
	KUNIT_EXPECT_EQ(test, memparse("1t", &end), 1024 * memparse("1g", &end));
	KUNIT_EXPECT_EQ(test, memparse("1p", &end), 1024 * memparse("1t", &end));
	KUNIT_EXPECT_EQ(test, memparse("1e", &end), 1024 * memparse("1p", &end));

	/* Upper and lower case are equivalent for every suffix. */
	KUNIT_EXPECT_EQ(test, memparse("3k", &end), memparse("3K", &end));
	KUNIT_EXPECT_EQ(test, memparse("3m", &end), memparse("3M", &end));
	KUNIT_EXPECT_EQ(test, memparse("3g", &end), memparse("3G", &end));
	KUNIT_EXPECT_EQ(test, memparse("3t", &end), memparse("3T", &end));
	KUNIT_EXPECT_EQ(test, memparse("3p", &end), memparse("3P", &end));
	KUNIT_EXPECT_EQ(test, memparse("3e", &end), memparse("3E", &end));
}

static void memparse_hex(struct kunit *test)
{
	check_memparse(test, "0x0", 0, 3);
	check_memparse(test, "0x10", 16, 4);
	check_memparse(test, "0X10", 16, 4);
	check_memparse(test, "0xff", 255, 4);
	check_memparse(test, "0xFF", 255, 4);
	check_memparse(test, "0xdeadbeef", 0xdeadbeefULL, 10);
	check_memparse(test, "0xffffffffffffffff", ULLONG_MAX, 18);
	/* hex digits followed by a suffix */
	check_memparse(test, "0x10k", 16 * KB, 5);
	check_memparse(test, "0x1M", MB, 4);
	check_memparse(test, "0x1000G", 0x1000ULL * GB, 7);
}

static void memparse_octal(struct kunit *test)
{
	check_memparse(test, "00", 0, 2);
	check_memparse(test, "010", 8, 3);
	check_memparse(test, "0777", 0777, 4);
	check_memparse(test, "010k", 8 * KB, 4);
	check_memparse(test, "020M", 16 * MB, 4);
	/* '8' and '9' are not octal digits: parsing stops there */
	check_memparse(test, "08", 0, 1);
	check_memparse(test, "0789", 7, 2);
}

static void memparse_stops_after_single_suffix(struct kunit *test)
{
	/* Only one suffix is consumed; a second one is left unparsed. */
	check_memparse(test, "1kk", KB, 2);
	check_memparse(test, "1KM", KB, 2);
	check_memparse(test, "1Mk", MB, 2);
	check_memparse(test, "1gG", GB, 2);
	check_memparse(test, "1EE", EB, 2);
}

static void memparse_trailing_garbage(struct kunit *test)
{
	/* Unknown trailing chars are left for the caller. */
	check_memparse(test, "1KB", KB, 2);
	check_memparse(test, "1MiB", MB, 2);
	check_memparse(test, "100 ", 100, 3);
	check_memparse(test, "100x", 100, 3);
	check_memparse(test, "100,200", 100, 3);
	check_memparse(test, "64M,128M", 64 * MB, 3);
	check_memparse(test, "16@0x1000", 16, 2);
	check_memparse(test, "1k@2M", KB, 2);
	check_memparse(test, "512:foo", 512, 3);
	check_memparse(test, "1$", 1, 1);
	check_memparse(test, "7b", 7, 1);
	check_memparse(test, "7B", 7, 1);
}

static void memparse_no_digits(struct kunit *test)
{
	/* No number at all: value 0, nothing consumed. */
	check_memparse(test, "", 0, 0);
	check_memparse(test, "abc", 0, 0);
	check_memparse(test, "xyz", 0, 0);
	check_memparse(test, " 1", 0, 0);
	check_memparse(test, "-1", 0, 0);
	check_memparse(test, "+1", 0, 0);
	check_memparse(test, "=5", 0, 0);
}

static void memparse_bare_suffix(struct kunit *test)
{
	/* A suffix with no digits: zero shifted is zero, suffix consumed. */
	check_memparse(test, "k", 0, 1);
	check_memparse(test, "K", 0, 1);
	check_memparse(test, "m", 0, 1);
	check_memparse(test, "M", 0, 1);
	check_memparse(test, "g", 0, 1);
	check_memparse(test, "G", 0, 1);
	check_memparse(test, "t", 0, 1);
	check_memparse(test, "T", 0, 1);
	check_memparse(test, "p", 0, 1);
	check_memparse(test, "P", 0, 1);
	check_memparse(test, "e", 0, 1);
	check_memparse(test, "E", 0, 1);
	check_memparse(test, "Kfoo", 0, 1);
}

static void memparse_non_suffix_letters(struct kunit *test)
{
	/* Letters adjacent to the suffix letters must not be treated as suffixes. */
	check_memparse(test, "1j", 1, 1);
	check_memparse(test, "1J", 1, 1);
	check_memparse(test, "1l", 1, 1);
	check_memparse(test, "1L", 1, 1);
	check_memparse(test, "1n", 1, 1);
	check_memparse(test, "1N", 1, 1);
	check_memparse(test, "1f", 1, 1);
	check_memparse(test, "1F", 1, 1);
	check_memparse(test, "1h", 1, 1);
	check_memparse(test, "1H", 1, 1);
	check_memparse(test, "1s", 1, 1);
	check_memparse(test, "1u", 1, 1);
	check_memparse(test, "1o", 1, 1);
	check_memparse(test, "1O", 1, 1);
	check_memparse(test, "1q", 1, 1);
	check_memparse(test, "1Q", 1, 1);
	check_memparse(test, "1d", 1, 1);
	check_memparse(test, "1D", 1, 1);
	check_memparse(test, "1z", 1, 1);
	check_memparse(test, "1Z", 1, 1);
	/* hex-looking letters after a decimal number are not digits either */
	check_memparse(test, "1a", 1, 1);
	check_memparse(test, "1c", 1, 1);
}

static void memparse_null_retptr(struct kunit *test)
{
	/* retptr is optional. */
	KUNIT_EXPECT_EQ(test, memparse("0", NULL), 0ULL);
	KUNIT_EXPECT_EQ(test, memparse("123", NULL), 123ULL);
	KUNIT_EXPECT_EQ(test, memparse("8K", NULL), 8 * KB);
	KUNIT_EXPECT_EQ(test, memparse("2G", NULL), 2 * GB);
	KUNIT_EXPECT_EQ(test, memparse("0x40M", NULL), 64 * MB);
	KUNIT_EXPECT_EQ(test, memparse("junk", NULL), 0ULL);
}

static void memparse_retptr_chaining(struct kunit *test)
{
	/* Typical use: parse several values out of one buffer via retptr. */
	const char *str = "16M@0x100000,4k,2G";
	char *p;

	KUNIT_EXPECT_EQ(test, memparse(str, &p), 16 * MB);
	KUNIT_EXPECT_EQ(test, *p, '@');
	KUNIT_EXPECT_EQ(test, memparse(p + 1, &p), 0x100000ULL);
	KUNIT_EXPECT_EQ(test, *p, ',');
	KUNIT_EXPECT_EQ(test, memparse(p + 1, &p), 4 * KB);
	KUNIT_EXPECT_EQ(test, *p, ',');
	KUNIT_EXPECT_EQ(test, memparse(p + 1, &p), 2 * GB);
	KUNIT_EXPECT_EQ(test, *p, '\0');
	KUNIT_EXPECT_PTR_EQ(test, (const char *)p, str + strlen(str));
}

static void memparse_large_values(struct kunit *test)
{
	check_memparse(test, "4095M", 4095 * MB, 5);
	check_memparse(test, "4096M", 4 * GB, 5);
	check_memparse(test, "1048576k", GB, 8);
	check_memparse(test, "1073741824", GB, 10);
	check_memparse(test, "1073741823k", 1073741823ULL * KB, 11);
	check_memparse(test, "16777215G", 16777215ULL * GB, 9);
	check_memparse(test, "255P", 255 * PB, 4);
	check_memparse(test, "0x7fffffffffffffff", 0x7fffffffffffffffULL, 18);
	/* largest multiplier that still fits in 64 bits for each suffix */
	check_memparse(test, "18014398509481983k",
		       18014398509481983ULL * KB, 18);
	check_memparse(test, "17592186044415M", 17592186044415ULL * MB, 15);
	check_memparse(test, "17179869183G", 17179869183ULL * GB, 12);
	check_memparse(test, "16777215T", 16777215ULL * TB, 9);
	check_memparse(test, "16383P", 16383ULL * PB, 6);
}

