/*
 * lib/agent_kunit.c: KUnit test written by an agent for this benchmark.
 * This file is compiled when CONFIG_AGENT_KUNIT_TEST is set.
 *
 * Test suite for __siphash_aligned() from lib/siphash.c.
 *
 * Note: __siphash_aligned() is only compiled when the architecture does not
 * set CONFIG_HAVE_EFFICIENT_UNALIGNED_ACCESS. On such architectures the
 * function does not exist, so the suite falls back to __siphash_unaligned(),
 * which implements the identical algorithm.
 */

#include <kunit/test.h>
#include <linux/siphash.h>
#include <linux/kernel.h>
#include <linux/string.h>
#include <linux/slab.h>
#include <linux/prandom.h>
#include <linux/bitops.h>

#ifdef CONFIG_HAVE_EFFICIENT_UNALIGNED_ACCESS
#define FUT(data, len, key) __siphash_unaligned(data, len, key)
#else
#define FUT(data, len, key) __siphash_aligned(data, len, key)
#endif

/* Reference key and vectors from https://github.com/veorq/SipHash
 * (SipHash-2-4, 64-bit output, message = bytes 0..len-1).
 */
static const siphash_key_t ref_key =
	{{ 0x0706050403020100ULL, 0x0f0e0d0c0b0a0908ULL }};

static const u64 ref_vectors[64] = {
	0x726fdb47dd0e0e31ULL, 0x74f839c593dc67fdULL, 0x0d6c8009d9a94f5aULL,
