#define BUF_SIZE 1024
#define MAX_REF_LEN 300

struct agent_ctx {
	u8 *buf;		/* 16-byte aligned, BUF_SIZE bytes */
	struct rnd_state rnd;
};

/*
 * Independent, deliberately naive byte-at-a-time SipHash-2-4 reference used
 * as an oracle. It shares nothing with lib/siphash.c except the
 * SIPHASH_PERMUTATION macro semantics, which are reimplemented here.
 */
static void ref_round(u64 *v)
{
	v[0] += v[1]; v[1] = rol64(v[1], 13); v[1] ^= v[0]; v[0] = rol64(v[0], 32);
	v[2] += v[3]; v[3] = rol64(v[3], 16); v[3] ^= v[2];
	v[0] += v[3]; v[3] = rol64(v[3], 21); v[3] ^= v[0];
	v[2] += v[1]; v[1] = rol64(v[1], 17); v[1] ^= v[2]; v[2] = rol64(v[2], 32);
}

static u64 ref_siphash(const u8 *in, size_t len, const siphash_key_t *key)
{
	u64 v[4] = {
		0x736f6d6570736575ULL, 0x646f72616e646f6dULL,
		0x6c7967656e657261ULL, 0x7465646279746573ULL
	};
	u64 b = (u64)len << 56;
	size_t i;

	v[3] ^= key->key[1];
	v[2] ^= key->key[0];
	v[1] ^= key->key[1];
	v[0] ^= key->key[0];

	for (i = 0; i + 8 <= len; i += 8) {
		u64 m = 0;
		int j;

		for (j = 7; j >= 0; j--)
			m = (m << 8) | in[i + j];
		v[3] ^= m;
		ref_round(v);
		ref_round(v);
		v[0] ^= m;
	}
	for (; i < len; i++)
		b |= (u64)in[i] << (8 * (i % 8));

	v[3] ^= b;
	ref_round(v);
	ref_round(v);
	v[0] ^= b;
	v[2] ^= 0xff;
	ref_round(v);
	ref_round(v);
	ref_round(v);
	ref_round(v);
	return v[0] ^ v[1] ^ v[2] ^ v[3];
}

static void fill_random(struct agent_ctx *ctx, u8 *p, size_t n)
{
	size_t i;

	for (i = 0; i < n; i++)
		p[i] = prandom_u32_state(&ctx->rnd);
}

static siphash_key_t random_key(struct agent_ctx *ctx)
{
	siphash_key_t k;

	fill_random(ctx, (u8 *)&k, sizeof(k));
	return k;
}

static int agent_test_init(struct kunit *test)
{
	struct agent_ctx *ctx;

	ctx = kunit_kzalloc(test, sizeof(*ctx), GFP_KERNEL);
	KUNIT_ASSERT_NOT_NULL(test, ctx);
	/* kmalloc of >= 16 bytes is at least 16-byte aligned via ARCH_KMALLOC_MINALIGN
	 * on most arches, but assert explicitly since we need alignment.
	 */
	ctx->buf = kunit_kmalloc(test, BUF_SIZE, GFP_KERNEL);
	KUNIT_ASSERT_NOT_NULL(test, ctx->buf);
	KUNIT_ASSERT_TRUE(test, IS_ALIGNED((unsigned long)ctx->buf, SIPHASH_ALIGNMENT));
	prandom_seed_state(&ctx->rnd, 0x5eed5eed5eed5eedULL);
	test->priv = ctx;
	return 0;
}

/* ---- Reference-vector tests ---------------------------------------------- */

static void agent_ref_vectors_all_lengths(struct kunit *test)
{
	struct agent_ctx *ctx = test->priv;
	u8 *in = ctx->buf;
	int i;

	for (i = 0; i < 64; i++)
		in[i] = i;

	for (i = 0; i < 64; i++)
		KUNIT_EXPECT_EQ_MSG(test, FUT(in, i, &ref_key), ref_vectors[i],
				    "len=%d", i);
}

static void agent_ref_vector_empty(struct kunit *test)
{
	struct agent_ctx *ctx = test->priv;

	/* Buffer contents must be irrelevant for len == 0. */
	memset(ctx->buf, 0xff, BUF_SIZE);
	KUNIT_EXPECT_EQ(test, FUT(ctx->buf, 0, &ref_key), ref_vectors[0]);
	memset(ctx->buf, 0x00, BUF_SIZE);
	KUNIT_EXPECT_EQ(test, FUT(ctx->buf, 0, &ref_key), ref_vectors[0]);
	KUNIT_EXPECT_EQ(test, FUT(ctx->buf, 0, &ref_key), 0x726fdb47dd0e0e31ULL);
}

static void agent_ref_vector_block_boundaries(struct kunit *test)
{
	struct agent_ctx *ctx = test->priv;
	u8 *in = ctx->buf;
	int i;
	static const int lens[] = { 1, 7, 8, 9, 15, 16, 17, 23, 24, 25,
				    31, 32, 33, 39, 40, 41, 47, 48, 49,
				    55, 56, 57, 63 };

	for (i = 0; i < 64; i++)
		in[i] = i;

	for (i = 0; i < ARRAY_SIZE(lens); i++)
		KUNIT_EXPECT_EQ_MSG(test, FUT(in, lens[i], &ref_key),
				    ref_vectors[lens[i]], "len=%d", lens[i]);
}

/* ---- Oracle cross-checks -------------------------------------------------- */

static void agent_matches_reference_impl(struct kunit *test)
{
	struct agent_ctx *ctx = test->priv;
	int len, trial;

	for (trial = 0; trial < 4; trial++) {
		siphash_key_t k = random_key(ctx);

		fill_random(ctx, ctx->buf, BUF_SIZE);
		for (len = 0; len <= MAX_REF_LEN; len++)
			KUNIT_EXPECT_EQ_MSG(test, FUT(ctx->buf, len, &k),
					    ref_siphash(ctx->buf, len, &k),
					    "trial=%d len=%d", trial, len);
	}
}

static void agent_matches_unaligned_impl(struct kunit *test)
{
	struct agent_ctx *ctx = test->priv;
	int len;
	siphash_key_t k = random_key(ctx);

	fill_random(ctx, ctx->buf, BUF_SIZE);
	for (len = 0; len <= BUF_SIZE; len++)
		KUNIT_EXPECT_EQ_MSG(test, FUT(ctx->buf, len, &k),
				    __siphash_unaligned(ctx->buf, len, &k),
				    "len=%d", len);
}

static void agent_matches_fixed_width_helpers(struct kunit *test)
{
	struct agent_ctx *ctx = test->priv;
	__le64 *w = (__le64 *)ctx->buf;
	__le32 *w32 = (__le32 *)ctx->buf;
	siphash_key_t k = random_key(ctx);

	fill_random(ctx, ctx->buf, 64);

	KUNIT_EXPECT_EQ(test, FUT(ctx->buf, 4, &k),
			siphash_1u32(le32_to_cpu(w32[0]), &k));
	KUNIT_EXPECT_EQ(test, FUT(ctx->buf, 8, &k),
			siphash_1u64(le64_to_cpu(w[0]), &k));
	KUNIT_EXPECT_EQ(test, FUT(ctx->buf, 8, &k),
			siphash_2u32(le32_to_cpu(w32[0]), le32_to_cpu(w32[1]), &k));
	KUNIT_EXPECT_EQ(test, FUT(ctx->buf, 12, &k),
			siphash_3u32(le32_to_cpu(w32[0]), le32_to_cpu(w32[1]),
				     le32_to_cpu(w32[2]), &k));
	KUNIT_EXPECT_EQ(test, FUT(ctx->buf, 16, &k),
			siphash_2u64(le64_to_cpu(w[0]), le64_to_cpu(w[1]), &k));
	KUNIT_EXPECT_EQ(test, FUT(ctx->buf, 24, &k),
			siphash_3u64(le64_to_cpu(w[0]), le64_to_cpu(w[1]),
				     le64_to_cpu(w[2]), &k));
	KUNIT_EXPECT_EQ(test, FUT(ctx->buf, 32, &k),
			siphash_4u64(le64_to_cpu(w[0]), le64_to_cpu(w[1]),
				     le64_to_cpu(w[2]), le64_to_cpu(w[3]), &k));
}

/* ---- Boundary / off-by-one tests ----------------------------------------- */

/*
 * For every length 1..72: flipping the last byte in range must change the
 * hash, and flipping the first byte *out of* range must not. This catches
 * both "reads one byte too few" and "reads one byte too many" bugs for every
 * tail size (left = 0..7) and across the first several 8-byte blocks.
 */
static void agent_last_byte_in_first_byte_out(struct kunit *test)
{
	struct agent_ctx *ctx = test->priv;
	siphash_key_t k = random_key(ctx);
	int len;

	for (len = 1; len <= 72; len++) {
		u64 base, h;

		fill_random(ctx, ctx->buf, BUF_SIZE);
		base = FUT(ctx->buf, len, &k);

		ctx->buf[len - 1] ^= 0x01;
		h = FUT(ctx->buf, len, &k);
		KUNIT_EXPECT_NE_MSG(test, h, base,
				    "len=%d: flipping byte %d did not change hash",
				    len, len - 1);
		ctx->buf[len - 1] ^= 0x01;

		ctx->buf[len] ^= 0xff;
		h = FUT(ctx->buf, len, &k);
		KUNIT_EXPECT_EQ_MSG(test, h, base,
				    "len=%d: flipping byte %d (out of range) changed hash",
				    len, len);
		ctx->buf[len] ^= 0xff;
	}
}

/* Every single byte position within the message must influence the result. */
static void agent_every_byte_matters(struct kunit *test)
{
	struct agent_ctx *ctx = test->priv;
	siphash_key_t k = random_key(ctx);
	static const int lens[] = { 1, 2, 3, 4, 5, 6, 7, 8, 9, 15, 16, 17, 31, 33, 64 };
	int li, pos;

	for (li = 0; li < ARRAY_SIZE(lens); li++) {
		int len = lens[li];
		u64 base;

		fill_random(ctx, ctx->buf, BUF_SIZE);
		base = FUT(ctx->buf, len, &k);
		for (pos = 0; pos < len; pos++) {
			ctx->buf[pos] ^= 0x80;
			KUNIT_EXPECT_NE_MSG(test, FUT(ctx->buf, len, &k), base,
					    "len=%d pos=%d", len, pos);
			ctx->buf[pos] ^= 0x80;
		}
	}
}

/* Each tail byte must land in its own bit position of the final block. */
static void agent_tail_byte_positions(struct kunit *test)
{
	struct agent_ctx *ctx = test->priv;
	siphash_key_t k = random_key(ctx);
	int left, pos;

	for (left = 1; left <= 7; left++) {
		int len = 8 + left;
		u64 seen[8];
		int i;

		memset(ctx->buf, 0, 32);
		fill_random(ctx, ctx->buf, 8);
		seen[0] = FUT(ctx->buf, len, &k);
		/* Setting the same value at distinct tail positions must give
		 * distinct hashes, i.e. positions are not conflated.
		 */
		for (pos = 0; pos < left; pos++) {
			memset(ctx->buf + 8, 0, 8);
			ctx->buf[8 + pos] = 0xa5;
			seen[pos + 1] = FUT(ctx->buf, len, &k);
			KUNIT_EXPECT_EQ_MSG(test, seen[pos + 1],
					    ref_siphash(ctx->buf, len, &k),
					    "left=%d pos=%d", left, pos);
			for (i = 0; i <= pos; i++)
				KUNIT_EXPECT_NE_MSG(test, seen[pos + 1], seen[i],
						    "left=%d pos=%d collides with %d",
						    left, pos, i - 1);
		}
	}
}

/*
 * The message length is mixed into the hash, so a message of n zero bytes and
 * one of n+1 zero bytes must differ even though all data bytes are equal.
 */
static void agent_length_is_hashed(struct kunit *test)
{
	struct agent_ctx *ctx = test->priv;
	siphash_key_t k = random_key(ctx);
	u64 prev;
	int len;

	memset(ctx->buf, 0, BUF_SIZE);
	prev = FUT(ctx->buf, 0, &k);
	for (len = 1; len <= 80; len++) {
		u64 h = FUT(ctx->buf, len, &k);

		KUNIT_EXPECT_NE_MSG(test, h, prev, "len=%d equals len=%d", len, len - 1);
		prev = h;
	}
	/* Also check zero-padding is not equivalent to a shorter message. */
	KUNIT_EXPECT_NE(test, FUT(ctx->buf, 7, &k), FUT(ctx->buf, 8, &k));
	KUNIT_EXPECT_NE(test, FUT(ctx->buf, 8, &k), FUT(ctx->buf, 16, &k));
}

static void agent_large_input(struct kunit *test)
{
	struct agent_ctx *ctx = test->priv;
	siphash_key_t k = random_key(ctx);
	u64 base;
	static const int lens[] = { 1000, 1017, 1023, 1024 };
	int i;

	fill_random(ctx, ctx->buf, BUF_SIZE);
	for (i = 0; i < ARRAY_SIZE(lens); i++)
		KUNIT_EXPECT_EQ_MSG(test, FUT(ctx->buf, lens[i], &k),
				    ref_siphash(ctx->buf, lens[i], &k),
				    "len=%d", lens[i]);

	base = FUT(ctx->buf, BUF_SIZE, &k);
	ctx->buf[BUF_SIZE / 2] ^= 1;
	KUNIT_EXPECT_NE(test, FUT(ctx->buf, BUF_SIZE, &k), base);
	ctx->buf[BUF_SIZE / 2] ^= 1;
	ctx->buf[BUF_SIZE - 1] ^= 1;
	KUNIT_EXPECT_NE(test, FUT(ctx->buf, BUF_SIZE, &k), base);
	ctx->buf[BUF_SIZE - 1] ^= 1;
	ctx->buf[0] ^= 1;
	KUNIT_EXPECT_NE(test, FUT(ctx->buf, BUF_SIZE, &k), base);
	ctx->buf[0] ^= 1;
	KUNIT_EXPECT_EQ(test, FUT(ctx->buf, BUF_SIZE, &k), base);
}

/* ---- Key handling ---------------------------------------------------------- */

static void agent_key_sensitivity(struct kunit *test)
{
	struct agent_ctx *ctx = test->priv;
	siphash_key_t k = random_key(ctx);
	siphash_key_t k2, swapped, zero = {{ 0, 0 }};
	int bit;
	static const int lens[] = { 0, 1, 8, 13, 64 };
	int li;

	fill_random(ctx, ctx->buf, 64);
	swapped.key[0] = k.key[1];
	swapped.key[1] = k.key[0];

	for (li = 0; li < ARRAY_SIZE(lens); li++) {
		int len = lens[li];
		u64 base = FUT(ctx->buf, len, &k);

		KUNIT_EXPECT_NE_MSG(test, FUT(ctx->buf, len, &swapped), base,
				    "len=%d: swapped key halves", len);
		KUNIT_EXPECT_NE_MSG(test, FUT(ctx->buf, len, &zero), base,
				    "len=%d: zero key", len);
		for (bit = 0; bit < 128; bit += 7) {
			k2 = k;
			k2.key[bit / 64] ^= 1ULL << (bit % 64);
			KUNIT_EXPECT_NE_MSG(test, FUT(ctx->buf, len, &k2), base,
					    "len=%d key bit %d", len, bit);
		}
	}
}

static void agent_zero_key_and_zero_data(struct kunit *test)
{
	struct agent_ctx *ctx = test->priv;
	siphash_key_t zero = {{ 0, 0 }};
	int len;

	memset(ctx->buf, 0, BUF_SIZE);
	for (len = 0; len <= 64; len++)
		KUNIT_EXPECT_EQ_MSG(test, FUT(ctx->buf, len, &zero),
				    ref_siphash(ctx->buf, len, &zero), "len=%d", len);
	memset(ctx->buf, 0xff, BUF_SIZE);
	for (len = 0; len <= 64; len++)
		KUNIT_EXPECT_EQ_MSG(test, FUT(ctx->buf, len, &zero),
				    ref_siphash(ctx->buf, len, &zero), "len=%d", len);
}

/* ---- Pointer / purity properties ------------------------------------------ */

static void agent_deterministic_and_pure(struct kunit *test)
{
	struct agent_ctx *ctx = test->priv;
	siphash_key_t k = random_key(ctx), kcopy = k;
	u8 *copy;
	u64 a, b;

	copy = kunit_kmalloc(test, BUF_SIZE, GFP_KERNEL);
	KUNIT_ASSERT_NOT_NULL(test, copy);
	fill_random(ctx, ctx->buf, BUF_SIZE);
	memcpy(copy, ctx->buf, BUF_SIZE);

	a = FUT(ctx->buf, 123, &k);
	b = FUT(ctx->buf, 123, &k);
	KUNIT_EXPECT_EQ(test, a, b);
	/* Neither input buffer nor key may be modified. */
	KUNIT_EXPECT_EQ(test, memcmp(copy, ctx->buf, BUF_SIZE), 0);
	KUNIT_EXPECT_EQ(test, k.key[0], kcopy.key[0]);
	KUNIT_EXPECT_EQ(test, k.key[1], kcopy.key[1]);
}

/* Hash depends only on the bytes in [data, data+len), not on their address. */
static void agent_address_independent(struct kunit *test)
{
	struct agent_ctx *ctx = test->priv;
	siphash_key_t k = random_key(ctx);
	int off, len;

	fill_random(ctx, ctx->buf, BUF_SIZE);
	for (off = 8; off <= 64; off += 8) {
		for (len = 0; len <= 40; len++) {
			u8 *copy = kunit_kmalloc(test, 64, GFP_KERNEL);

			KUNIT_ASSERT_NOT_NULL(test, copy);
			memset(copy, 0xee, 64);
			memcpy(copy, ctx->buf + off, len);
			KUNIT_EXPECT_EQ_MSG(test, FUT(ctx->buf + off, len, &k),
					    FUT(copy, len, &k),
					    "off=%d len=%d", off, len);
			kunit_kfree(test, copy);
		}
	}
}

static void agent_no_trivial_collisions(struct kunit *test)
{
	struct agent_ctx *ctx = test->priv;
	siphash_key_t k = random_key(ctx);
	u64 hashes[65];
	int i, j;

	/* Messages 0..64 bytes of counting data must all hash differently. */
	for (i = 0; i < 64; i++)
		ctx->buf[i] = i;
	for (i = 0; i <= 64; i++)
		hashes[i] = FUT(ctx->buf, i, &k);
	for (i = 0; i <= 64; i++)
		for (j = i + 1; j <= 64; j++)
			KUNIT_EXPECT_NE_MSG(test, hashes[i], hashes[j],
					    "len %d collides with len %d", i, j);
	/* Output must not be trivially zero or equal to the length. */
	for (i = 0; i <= 64; i++) {
		KUNIT_EXPECT_NE_MSG(test, hashes[i], 0ULL, "len=%d", i);
		KUNIT_EXPECT_NE_MSG(test, hashes[i], (u64)i, "len=%d", i);
	}
}

static struct kunit_case agent_test_cases[] = {
	KUNIT_CASE(agent_ref_vectors_all_lengths),
	KUNIT_CASE(agent_ref_vector_empty),
	KUNIT_CASE(agent_ref_vector_block_boundaries),
	KUNIT_CASE(agent_matches_reference_impl),
	KUNIT_CASE(agent_matches_unaligned_impl),
	KUNIT_CASE(agent_matches_fixed_width_helpers),
	KUNIT_CASE(agent_last_byte_in_first_byte_out),
	KUNIT_CASE(agent_every_byte_matters),
	KUNIT_CASE(agent_tail_byte_positions),
	KUNIT_CASE(agent_length_is_hashed),
	KUNIT_CASE(agent_large_input),
	KUNIT_CASE(agent_key_sensitivity),
	KUNIT_CASE(agent_zero_key_and_zero_data),
	KUNIT_CASE(agent_deterministic_and_pure),
	KUNIT_CASE(agent_address_independent),
	KUNIT_CASE(agent_no_trivial_collisions),
	{}
};

static struct kunit_suite agent_test_suite = {
	.name = "agent_test",
	.init = agent_test_init,
	.test_cases = agent_test_cases,
};

kunit_test_suite(agent_test_suite);

