/* Independent byte-at-a-time reference: SipHash-1-3 folded to 32 bits. */
static u32 ref_hsiphash(const u8 *data, size_t len, const hsiphash_key_t *key)
{
	u64 v0 = SIPHASH_CONST_0 ^ key->key[0];
	u64 v1 = SIPHASH_CONST_1 ^ key->key[1];
	u64 v2 = SIPHASH_CONST_2 ^ key->key[0];
	u64 v3 = SIPHASH_CONST_3 ^ key->key[1];
	u64 b = (u64)len << 56;
	size_t i, full = len - (len % 8);
	u64 m;

	for (i = 0; i < full; i += 8) {
		m = get_unaligned_le64(data + i);
		v3 ^= m;
		SIPHASH_PERMUTATION(v0, v1, v2, v3);
		v0 ^= m;
	}
	for (i = full; i < len; i++)
		b |= (u64)data[i] << (8 * (i - full));
	v3 ^= b;
	SIPHASH_PERMUTATION(v0, v1, v2, v3);
	v0 ^= b;
	v2 ^= 0xff;
	SIPHASH_PERMUTATION(v0, v1, v2, v3);
	SIPHASH_PERMUTATION(v0, v1, v2, v3);
	SIPHASH_PERMUTATION(v0, v1, v2, v3);
	return (u32)((v0 ^ v1) ^ (v2 ^ v3));
}
