/* Independent byte-at-a-time reference: HalfSipHash-1-3. */
static u32 ref_hsiphash(const u8 *data, size_t len, const hsiphash_key_t *key)
{
	u32 v0 = HSIPHASH_CONST_0 ^ key->key[0];
	u32 v1 = HSIPHASH_CONST_1 ^ key->key[1];
	u32 v2 = HSIPHASH_CONST_2 ^ key->key[0];
	u32 v3 = HSIPHASH_CONST_3 ^ key->key[1];
	u32 b = (u32)len << 24;
	size_t i, full = len - (len % 4);
	u32 m;

	for (i = 0; i < full; i += 4) {
		m = get_unaligned_le32(data + i);
		v3 ^= m;
		HSIPHASH_PERMUTATION(v0, v1, v2, v3);
		v0 ^= m;
	}
	for (i = full; i < len; i++)
		b |= (u32)data[i] << (8 * (i - full));
	v3 ^= b;
	HSIPHASH_PERMUTATION(v0, v1, v2, v3);
	v0 ^= b;
	v2 ^= 0xff;
	HSIPHASH_PERMUTATION(v0, v1, v2, v3);
	HSIPHASH_PERMUTATION(v0, v1, v2, v3);
	HSIPHASH_PERMUTATION(v0, v1, v2, v3);
	return v1 ^ v3;
}
