#define BUF_LEN 256

static void fill_pattern(u8 *buf, size_t len, u32 seed)
{
	size_t i;

	for (i = 0; i < len; i++) {
		seed = seed * 1103515245U + 12345U;
		buf[i] = (u8)(seed >> 16);
	}
}

/* Known-answer test: lengths 0..63 of the byte sequence 0,1,2,... */
static void agent_hsiphash_kat(struct kunit *test)
{
	u8 in[64] __aligned(HSIPHASH_ALIGNMENT);
	unsigned int i;

	for (i = 0; i < 64; i++)
		in[i] = i;
	for (i = 0; i < 64; i++)
		KUNIT_EXPECT_EQ_MSG(test, __hsiphash_aligned(in, i, &kat_key),
				    kat_vectors[i], "len %u", i);
}

/* Empty input: depends only on the key; must equal len-0 vector. */
static void agent_hsiphash_empty(struct kunit *test)
{
	u8 in[8] __aligned(HSIPHASH_ALIGNMENT);
	hsiphash_key_t k2 = {{ 0, 0 }};
	u32 h0, h1;

	memset(in, 0xff, sizeof(in));
	KUNIT_EXPECT_EQ(test, __hsiphash_aligned(in, 0, &kat_key), kat_vectors[0]);
	/* Contents of the buffer must not influence a zero-length hash. */
	h0 = __hsiphash_aligned(in, 0, &k2);
	memset(in, 0x00, sizeof(in));
	h1 = __hsiphash_aligned(in, 0, &k2);
	KUNIT_EXPECT_EQ(test, h0, h1);
	KUNIT_EXPECT_EQ(test, h1, ref_hsiphash(in, 0, &k2));
	/* ...but the key must. */
	KUNIT_EXPECT_NE(test, h1, __hsiphash_aligned(in, 0, &kat_key));
}

/* Consistency with the unaligned variant and the fixed-size helpers. */
static void agent_hsiphash_matches_siblings(struct kunit *test)
{
	u8 in[64] __aligned(HSIPHASH_ALIGNMENT);
	unsigned int i;

	fill_pattern(in, sizeof(in), 7);
	for (i = 0; i <= 64; i++)
		KUNIT_EXPECT_EQ_MSG(test, __hsiphash_aligned(in, i, &kat_key),
				    __hsiphash_unaligned(in, i, &kat_key),
				    "len %u", i);

	KUNIT_EXPECT_EQ(test, __hsiphash_aligned(in, 4, &kat_key),
			hsiphash_1u32(get_unaligned_le32(in), &kat_key));
	KUNIT_EXPECT_EQ(test, __hsiphash_aligned(in, 8, &kat_key),
			hsiphash_2u32(get_unaligned_le32(in),
				      get_unaligned_le32(in + 4), &kat_key));
	KUNIT_EXPECT_EQ(test, __hsiphash_aligned(in, 12, &kat_key),
			hsiphash_3u32(get_unaligned_le32(in),
				      get_unaligned_le32(in + 4),
				      get_unaligned_le32(in + 8), &kat_key));
	KUNIT_EXPECT_EQ(test, __hsiphash_aligned(in, 16, &kat_key),
			hsiphash_4u32(get_unaligned_le32(in),
				      get_unaligned_le32(in + 4),
				      get_unaligned_le32(in + 8),
				      get_unaligned_le32(in + 12), &kat_key));
}

/* Compare against the byte-at-a-time reference over many lengths/keys. */
static void agent_hsiphash_reference(struct kunit *test)
{
	u8 *in;
	hsiphash_key_t key;
	unsigned int len, k;

	in = kunit_kzalloc(test, BUF_LEN, GFP_KERNEL);
	KUNIT_ASSERT_NOT_NULL(test, in);
	KUNIT_ASSERT_TRUE(test, IS_ALIGNED((unsigned long)in, HSIPHASH_ALIGNMENT));

	for (k = 0; k < 4; k++) {
		key.key[0] = (unsigned long)0x9e3779b97f4a7c15ULL * (k + 1);
		key.key[1] = ~(unsigned long)0x6a09e667f3bcc909ULL * (k + 3);
		fill_pattern(in, BUF_LEN, 0x1234 + k);
		for (len = 0; len <= BUF_LEN; len++)
			KUNIT_EXPECT_EQ_MSG(test,
					    __hsiphash_aligned(in, len, &key),
					    ref_hsiphash(in, len, &key),
					    "key %u len %u", k, len);
	}
}

/*
 * Tail handling: every byte inside [0, len) must affect the hash, and
 * no byte at or beyond len may. Covers all residues modulo the word size
 * on both sides of several word boundaries.
 */
static void agent_hsiphash_tail_bytes(struct kunit *test)
{
	u8 in[3 * HSIP_WORD + 8] __aligned(HSIPHASH_ALIGNMENT);
	unsigned int len, pos;
	u32 base, h;

	for (len = 0; len <= 3 * HSIP_WORD; len++) {
		fill_pattern(in, sizeof(in), len + 99);
		base = __hsiphash_aligned(in, len, &kat_key);

		/* Each in-range byte changes the result. */
		for (pos = 0; pos < len; pos++) {
			in[pos] ^= 0x5a;
			h = __hsiphash_aligned(in, len, &kat_key);
			in[pos] ^= 0x5a;
			KUNIT_EXPECT_NE_MSG(test, h, base,
					    "len %u byte %u ignored", len, pos);
		}
		/* Out-of-range bytes (up to 8 past the end) do not. */
		for (pos = len; pos < len + 8 && pos < sizeof(in); pos++) {
			in[pos] = ~in[pos];
			h = __hsiphash_aligned(in, len, &kat_key);
			in[pos] = ~in[pos];
			KUNIT_EXPECT_EQ_MSG(test, h, base,
					    "len %u byte %u leaked", len, pos);
		}
	}
}

/* Length is part of the hash: same prefix, different lengths differ. */
static void agent_hsiphash_length_sensitive(struct kunit *test)
{
	u8 in[2 * HSIP_WORD + 1] __aligned(HSIPHASH_ALIGNMENT);
	unsigned int a, b;

	memset(in, 0, sizeof(in));
	/* All-zero bytes: only the length distinguishes these inputs. */
	for (a = 0; a <= 2 * HSIP_WORD; a++)
		for (b = a + 1; b <= 2 * HSIP_WORD; b++)
			KUNIT_EXPECT_NE_MSG(test,
					    __hsiphash_aligned(in, a, &kat_key),
					    __hsiphash_aligned(in, b, &kat_key),
					    "len %u vs %u collide", a, b);
}

/* Each key word matters, and each bit of each key word matters. */
static void agent_hsiphash_key_sensitive(struct kunit *test)
{
	u8 in[16] __aligned(HSIPHASH_ALIGNMENT);
	hsiphash_key_t key;
	unsigned int w, bit;
	u32 base;

	fill_pattern(in, sizeof(in), 42);
	key = kat_key;
	base = __hsiphash_aligned(in, sizeof(in), &key);

	for (w = 0; w < 2; w++) {
		for (bit = 0; bit < BITS_PER_LONG; bit++) {
			key = kat_key;
			key.key[w] ^= 1UL << bit;
			KUNIT_EXPECT_NE_MSG(test,
					    __hsiphash_aligned(in, sizeof(in), &key),
					    base, "key[%u] bit %u ignored", w, bit);
		}
	}
	/* Swapping the two key halves must also change the result. */
	key.key[0] = kat_key.key[1];
	key.key[1] = kat_key.key[0];
	KUNIT_EXPECT_NE(test, __hsiphash_aligned(in, sizeof(in), &key), base);
}

/* Determinism and independence from the buffer's absolute address. */
static void agent_hsiphash_deterministic(struct kunit *test)
{
	u8 a[40] __aligned(HSIPHASH_ALIGNMENT);
	u8 *b;
	unsigned int len;

	b = kunit_kzalloc(test, sizeof(a), GFP_KERNEL);
	KUNIT_ASSERT_NOT_NULL(test, b);
	fill_pattern(a, sizeof(a), 3);
	memcpy(b, a, sizeof(a));

	for (len = 0; len <= sizeof(a); len++) {
		u32 h1 = __hsiphash_aligned(a, len, &kat_key);
		u32 h2 = __hsiphash_aligned(a, len, &kat_key);
		u32 h3 = __hsiphash_aligned(b, len, &kat_key);

		KUNIT_EXPECT_EQ_MSG(test, h1, h2, "len %u", len);
		KUNIT_EXPECT_EQ_MSG(test, h1, h3, "len %u", len);
	}
}

/* Long inputs spanning many words, including a page-sized buffer. */
static void agent_hsiphash_long(struct kunit *test)
{
	u8 *in;
	size_t len;
	static const size_t lens[] = { 65, 127, 128, 129, 255, 256, 257,
				       1023, 1024, 1025, 4095, 4096 };
	unsigned int i;

	in = kunit_kzalloc(test, 4096, GFP_KERNEL);
	KUNIT_ASSERT_NOT_NULL(test, in);
	fill_pattern(in, 4096, 0xbeef);

	for (i = 0; i < ARRAY_SIZE(lens); i++) {
		len = lens[i];
		KUNIT_EXPECT_EQ_MSG(test, __hsiphash_aligned(in, len, &kat_key),
				    ref_hsiphash(in, len, &kat_key), "len %zu", len);
		KUNIT_EXPECT_EQ_MSG(test, __hsiphash_aligned(in, len, &kat_key),
				    __hsiphash_unaligned(in, len, &kat_key),
				    "len %zu", len);
	}
	/* Flipping the very last byte of the longest input must matter. */
	{
		u32 before = __hsiphash_aligned(in, 4096, &kat_key);

		in[4095] ^= 1;
		KUNIT_EXPECT_NE(test, __hsiphash_aligned(in, 4096, &kat_key), before);
		in[4095] ^= 1;
		KUNIT_EXPECT_EQ(test, __hsiphash_aligned(in, 4096, &kat_key), before);
	}
}

/* Single-bit input changes should never leave the hash unchanged. */
static void agent_hsiphash_avalanche(struct kunit *test)
{
	u8 in[24] __aligned(HSIPHASH_ALIGNMENT);
	unsigned int bit;
	u32 base;

	fill_pattern(in, sizeof(in), 11);
	base = __hsiphash_aligned(in, sizeof(in), &kat_key);
	for (bit = 0; bit < sizeof(in) * 8; bit++) {
		in[bit / 8] ^= 1 << (bit % 8);
		KUNIT_EXPECT_NE_MSG(test, __hsiphash_aligned(in, sizeof(in), &kat_key),
				    base, "bit %u", bit);
		in[bit / 8] ^= 1 << (bit % 8);
	}
	KUNIT_EXPECT_EQ(test, __hsiphash_aligned(in, sizeof(in), &kat_key), base);
}

