	KUNIT_CASE(agent_hsiphash_empty),
	KUNIT_CASE(agent_hsiphash_matches_siblings),
	KUNIT_CASE(agent_hsiphash_reference),
	KUNIT_CASE(agent_hsiphash_tail_bytes),
	KUNIT_CASE(agent_hsiphash_length_sensitive),
	KUNIT_CASE(agent_hsiphash_key_sensitive),
	KUNIT_CASE(agent_hsiphash_deterministic),
	KUNIT_CASE(agent_hsiphash_long),
	KUNIT_CASE(agent_hsiphash_avalanche),
	{}
};

static struct kunit_suite agent_test_suite = {
	.name = "agent_test",
	.test_cases = agent_test_cases,
};

kunit_test_suite(agent_test_suite);

